# -*- coding: utf-8 -*-
"""data_proj_cards_h.py —— ㉕ 一条 I2C 总线挂多个器件 + AT24C02 掉电保存参数"""

FLOW_P25_I2C_EEPROM = r"""
/* ============ ㉕ 一条 I2C 总线挂多个器件 + AT24C02 掉电保存参数 ============ */
{m:"流程", t:"flow", n:"㉕ 一条 I2C 总线挂多个器件 + AT24C02 掉电保存参数", d:"I2C 只用两根线就能挂一堆器件，代价是所有器件共享同一个时序资源：地址冲突、页写回卷、写周期不应答、多任务交错，任何一条都能让参数静默损坏。本卡先在一条总线上把 24C02 / MPU6050 / OLED 全部扫出来，再落到参数保存这件具体事上：MAGIC 判首次上电、CRC16 判数据是不是可信、A/B 双份轮换抗掉电，让“上次设的阈值”真的能跨过断电。",
 f:[
  ["先盘清一条总线上到底能挂几个器件、地址怎么分","I2C 是地址寻址的共享总线：两根线（SDA/SCL）可以并行挂很多从机，只要7 位地址互不相同。本项目板2 的 I2C1（PB8/PB9）上就同时挂着 24C02(0x50)、MPU6050(0x68)、以及外接排针上的 OLED(0x3C)、AHT10(0x38)、SHT30(0x44)，谁都不妨碍谁。限制有三个：地址冲突、总线电容、上拉强度；“挂不上”通常是这三条之一，而非数量超限","地址冲突最隐蔽：BMP280 和 BME280 是同一个地址（0x76/0x77），只能靠读寄存器 0xD0 的芯片 ID（0x58 = BMP280、0x60 = BME280）来区分，没法用地址把它们分开"],
  ["硬件三件事：4.7k 上拉、必须共地、电容别超 400pF","I2C 的电气形态是开漏 + 上拉：任何一个器件都只能把线拉低，拉高全靠上拉电阻。所以 SDA/SCL 各要一只约 4.7k 上拉到 3.3V（本项目板载已有，外接模块要确认模块是否自带）。上拉太弱（阻值太大）上升沿变缓，400kHz 下波形爬不起来；上拉太强（阻值太小）从机灌电流超限。标准模式 100kHz / 快速模式 400kHz；总线电容上限约 400pF，杜邦线每根约 20~50pF，线一长就只能降速","板载 24C02 用的是 100kHz（AT24C02_I2C_SPEED = 100000UL），头文件写得很直白：EEPROM 别跑 400k"],
  ["初始化 + 扫描：先把总线上所有应答的地址列出来","SYS_I2C_Init(SYS_I2C_1, 100000) 把总线拉起来（时钟、开漏引脚、速率）；SYS_I2C_Scan(bus, found, max) 在 0x08~0x77 区间逐地址发 START + 地址，收到 ACK 就记进 found[]，返回找到的个数。这是“一根线挂多个器件”的验收手段：扫描结果与地址表一一对应，可发现接错、地址脚接反、模块未供电","found[] 里写的是7 位地址；函数说明里明确写了“可传 0 只要计数”。另外 Scan 内部自己会加锁，但持外层锁时别再调它，本项目是递归锁，同任务嵌套没事，别的任务会干等整个扫描过程"],
  ["单寄存器读写：WriteByte / ReadByte 是 90% 器件的通用姿势","绝大多数 I2C 器件都是“寄存器型”：先给一个寄存器号，再读写数据。SYS_I2C_WriteByte(bus, addr7, reg, data) 的时序是 START → 器件写地址 → 寄存器号 → 数据 → STOP；SYS_I2C_ReadByte(bus, addr7, reg, out) 则是 START → 写地址 → 寄存器号 → ReSTART → 读地址 → 数据 → NACK → STOP。第二种叫“先下指针再读”，是 I2C 器件读寄存器的标准动作","MPU6050 的 WHO_AM_I 在 0x75，读出来应该是 0x68；读不到或读回 0x00/0xFF，先查这个寄存器能快速判断器件到底活没活"],
  ["两种特殊时序：只发命令（WriteCmd）与不发寄存器直接读（ReadRaw）","有些器件不是“寄存器型”：BH1750 拿到一个字节就直接当命令（0x01 = 上电、0x10 = 连续 H 分辨率），没有有寄存器号概念；它的测量结果又是“直接读两字节”，不需要先写指针。所以库给了两个专用入口：SYS_I2C_WriteCmd(bus, addr7, cmd) 只发一个命令字节就 STOP；SYS_I2C_ReadRaw(bus, addr7, buf, len) 发完读地址直接收字节","这里有个静默失败的问题：不能用 SYS_I2C_WriteBytes(bus, addr, 0, NULL, 0) 来发命令，源码判了 buf == 0 || len == 0 就直接返回 SYS_I2C_ERR_PARAM（-1），字节一个都没发出去，而只看到“参数非法”，很容易误判成器件坏了"],
  ["16 位寄存器器件：WriteReg16 / ReadReg16","有一类器件（大容量 EEPROM、某些传感器）内部地址是 16 位，需要两个字节的寄存器号（高字节在前）。这时用 SYS_I2C_WriteReg16 / SYS_I2C_ReadReg16，参数里的 reg 是 uint16_t，函数内部拆成先后两个字节发出去。用 WriteBytes 硬拼也行，但那样就把“高字节在前”这个约定散落在业务代码里了","本项目 24C02 只有 256 字节，寄存器号 8 位就够，所以用 WriteByte/WriteBytes 才是对的；换成 24C32/24C64 就必须切到 Reg16 那一组，否则后半片永远读写不到"],
  ["AT24C02 的前两条硬规矩：一次页写 8 字节，写完要等 5ms","24C02 = 2Kbit = 256 字节，I2C 地址 0x50（A2A1A0 全接地）。它内部有 8 字节的页缓冲：一次写命令最多写 8 字节（且不能跨页），芯片收完 STOP 之后要花约 5ms 把数据真正压进浮栅，这期间它不对任何地址应答。教训就两条：写参数的耗时是“页数 × 5ms”，绝不能放在中断里；以及“不等就接着写下一笔”会拿到 NACK，表现为 SYS_I2C_ERR_ADDR = -3","教科书做法是死等 5ms；本项目 at24c02.c 用的是更好的办法，写完后用 SYS_I2C_IsDeviceReady 反复探地址，一有 ACK 就说明写完了，通常 2~3ms 就返回，参数存得快近一倍，并且留了 200 次轮询 + delay_ms(5) 的双保险，芯片坏了也不会死循环"],
  ["页写会回卷，跨页必须自己拆，这是 24C02 最贵的一课","24C02 内部地址的低 3 位是页内指针，高 5 位才是页号；连续写的时候低 3 位到 7 就回卷到本页开头，而不是进位到下一页。于是 AT24C02_WriteBytes(250, buf, 10) 的真实行为是：先写 250..255 六个字节，再把剩下 4 个字节写到 0..3，正好覆盖掉 MAGIC 区和参数头，而且不报任何错。所以“把结构体整体写进去”之前，必须先检查 `addr % 8 + len <= 8`，不满足就按 8 字节边界拆成多次写","本项目 at24c02.c 已经做了这件事：循环里算 in_page = 8 - ((addr + done) & 7)，取 n = min(剩余, in_page) 分片写，每片写完等一次写周期；并且函数开头就用 `(uint16_t)addr + len > 256` 把越界直接拦成返回 1，不再依赖“芯片会绕回”。读它、信它，但要知道它在替挡什么"],
  ["参数保存的可靠写法：MAGIC + 版本 + 长度 + CRC16，缺一不可","EEPROM 里读出来的东西永远不能当成可信数据：空片是全 0xFF、上次写到一半掉电是半截数据、页写回卷是错位数据。所以一份参数要有自己的“信封”：4 字节 MAGIC 判“到底存过没有”（本项目用 AT24C02_IsMagicSet(addr, magic)，1 = 魔数在 = 参数存过）、版本号 + 长度判格式对不对、CRC16-MODBUS 判内容有没有坏。三项全过才采用，任何一项不过就整套回落到默认值并重写一次，永远不要让半个参数结构体进入业务逻辑","另一个必须做的动作：读完校验通过之后，把内存里结构体的 crc/len/magic 字段清零再交出去，免得写业务代码的人误以为它们是有效数据。CRC16-MODBUS 在本项目板2 叫 MODBUS_CRC16(buf, len)，多项式 0xA001、初值 0xFFFF、低字节在前"],
  ["想抗掉电就上 A/B 双份轮换（和 ⑱ SPI Flash 那张卡同一个思路）","CRC 能告诉“这页坏了”，但不能告诉“坏的那一页要不要紧”，如果只有一份，坏了就只剩默认值。更稳的做法是两份轮换：在参数区开两块（A 和 B，各占一页 8 字节以上），每份都带自己的 MAGIC + CRC；保存时先写非当前那份，校验通过后再更新一个“当前有效份”标志。这样无论在哪一刻掉电，A、B 里至少有一份是完整可用的，最坏也只丢最后一次改动","⑱ SPI Flash 断网缓存日志卡用的是同一套哲学（先写数据再写状态、状态只用一次原子写更新），两张卡要互相引用着看：“写完再改标志”是可恢复写入的通用套路，跟介质是 EEPROM 还是 Flash 无关"],
  ["收尾：多任务加锁、中断禁入、排错三步走","I2C 事务是“START → 地址 → 数据 → STOP”的连续时序，两个任务交错就会让从机收错命令。本项目每条总线一把递归互斥量：sys_i2c.c 的 11 个公共入口（Init / IsDeviceReady / WriteByte / ReadByte / WriteBytes / ReadBytes / ReadRaw / WriteCmd / BusReset / Scan / WriteReg16 / ReadReg16）内部已经自动加锁；但“写一份参数 = 擦 + 多片写 + 改标志”这种多笔连续操作，必须自己在外面再包一层 SYS_I2C_Lock/Unlock。中断上下文里加锁会被 __get_IPSR 判断后直接跳过（FreeRTOS 互斥量在 ISR 里阻塞是非法的），所以在中断里调 I2C 是没有互斥保护的，正确做法是把访问丢给任务（队列/信号量）","排错固定三步：① SYS_I2C_Scan 扫一遍，看 0x50 在不在；② 读回全 0xFF 就是没写进去或写周期没等完；③ 偶发 NACK（-3）先想“是不是写周期内又发起新事务”，再想上拉和线长。真遇到某个器件把 SDA 拉死，SYS_I2C_BusReset(bus) 会发 9 个时钟 + STOP 把它踢出状态机，然后重新初始化本机 I2C"]
 ],
 a:[
  ["I2C1（本项目推荐只用它）","SCL = PB8 / SDA = PB9","板载 24C02 + MPU6050，外接 OLED/AHT10/SHT30 也接这里；板上已有 4.7k 上拉"],
  ["I2C2","SCL = PB10 / SDA = PB11","与 USART3 的 TX/RX（ESP8266 接口）复用，二选一"],
  ["I2C3","SCL = PA8 / SDA = PC9","PA8 与板载红外接收头二选一；PC9 = SDIO_D1，用 TF 卡就不能用 I2C3"],
  ["总线枚举","SYS_I2C_COUNT = 3，SYS_I2C_1 = 0 / SYS_I2C_2 = 1 / SYS_I2C_3 = 2","换总线只改驱动头里的一个宏"],
  ["错误码表","OK = 0 / ERR_PARAM = -1 / ERR_START = -2 / ERR_ADDR = -3 / ERR_DATA = -4 / ERR_TIMEOUT = -5 / ERR_BUS = -6","用 SYS_I2C_ErrStr(err) 转中文；-3 无应答最常见，-5 才考虑 BusReset"],
  ["地址总表","24C02 = 0x50；MPU6050 = 0x68；AHT10 = 0x38；SHT30 = 0x44；SSD1306 = 0x3C/0x3D（SA0 决定）；BMP280 = 0x76/0x77；BH1750 = 0x23/0x5C；CCS811 = 0x5A/0x5B","BMP280 与 BME280 同址，靠 0xD0 的芯片 ID 区分（0x58 / 0x60）"],
  ["7 位 vs 8 位地址","手册给写地址 0xD0 / 读地址 0xD1 时，要 0xD0 >> 1 = 0x68 再传","库里所有 addr7 参数一律是 7 位；左移后的 8 位地址传进去必然 NACK"],
  ["上拉 / 速率 / 电容","SDA、SCL 各 4.7k 上拉到 3.3V；标准 100kHz、快速 400kHz；总线电容 ≤ 约 400pF","24C02 驱动定的是 100kHz（AT24C02_I2C_SPEED = 100000UL），EEPROM 别跑 400k"],
  ["AT24C02 容量与页","256 字节（0x00~0xFF）；页 = 8 字节；写周期典型 5ms（最大 10ms）","AT24C02_TOTAL_SIZE / AT24C02_PAGE_SIZE / AT24C02_WRITE_MS"],
  ["页写边界公式","可一次写的长度 = 8 - ((addr) & 7)，且起始地址必须与本次长度同页","超出就会回卷到本页开头，覆盖 MAGIC/参数头且不报错"],
  ["地址规划（.h 已给）","MAGIC 0x00~0x03（AT24C02_MAGIC_VALUE = 0xA5）；参数区 0x10~0x7F；校准区 0x80~0xEF","头文件里有编译期自检 #if (AT24C02_ADDR_CALIB >= 256) #error"],
  ["锁的粒度","每条总线一把递归互斥量，粒度 = 一次完整事务","11 个公共入口内部已自动加锁；多笔连续操作要自己外层再加一层"],
  ["中断上下文","加锁被 __get_IPSR() 判断后直接跳过","ISR 里调 I2C 没有互斥，只能靠队列/信号量把访问搬回任务里"]
 ],
 e:"/* ============================================================\n *  ㉕ 一条 I2C 总线挂多个器件 + AT24C02 掉电保存参数\n *  平台：STM32F407 · 板2（数据通信端）\n *  总线：I2C1，SCL = PB8 / SDA = PB9，板上已有 4.7k 上拉\n *  器件：AT24C02(0x50) + MPU6050(0x68) + 外接 OLED(0x3C) / AHT10(0x38)\n *  依赖：sys_i2c.h + at24c02.h（本项目已有，本文件不改它们）\n * ============================================================ */\n#include \"stm32f4xx.h\"\n#include \"sys_i2c.h\"\n#include \"at24c02.h\"\n#include \"modbus.h\"      /* MODBUS_CRC16(buf, len)：多项式 0xA001，初值 0xFFFF */\n\n#include <string.h>\n\n/* ---------------- ① 总线上的器件清单（7 位地址） ---------------- */\n#define BUS_EEPROM    SYS_I2C_ADDR_24C02      /* 0x50 板载 EEPROM */\n#define BUS_MPU6050   SYS_I2C_ADDR_MPU6050    /* 0x68 板载六轴 AD0=0 */\n#define BUS_OLED      SYS_I2C_ADDR_SSD1306    /* 0x3C 外接 OLED */\n#define BUS_AHT10     SYS_I2C_ADDR_AHT10      /* 0x38 外接温湿度 */\n\n/* ---------------- ② 参数区的“信封”布局（0x10 起，避开 MAGIC 区） ---------\n *   0x10  4 字节 MAGIC  “P25A”\n *   0x14  1 字节 版本    改了字段就得改它\n *   0x15  1 字节 长度    = sizeof(Param_t)，防止结构体变了还去读老数据\n *   0x16  2 字节 CRC16   覆盖 [0x10, 0x16) 共 6 字节\n *   0x18  N 字节 参数体\n * ============================================================ */\n#define P25_MAGIC0     0x50U    /* 'P' */\n#define P25_MAGIC1     0x32U    /* '2' */\n#define P25_MAGIC2     0x35U    /* '5' */\n#define P25_MAGIC3     0x41U    /* 'A' */\n#define P25_VER        1U\n#define P25_ADDR_HDR   0x10U\n#define P25_ADDR_BODY  0x18U\n\n/* 为什么参数体不放在 0x14：把定长头（MAGIC+版本+长度+CRC）与变长体分开，\n *   以后加字段只改 P25_VER 和结构体，头部布局不动，老固件的头依然能读。 */\n\ntypedef struct {\n    uint16_t kp_x100;      /* PID Kp ×100：1.25 → 125 */\n    uint16_t ki_x100;      /* PID Ki ×100 */\n    uint16_t kd_x100;      /* PID Kd ×100 */\n    uint16_t temp_alarm;   /* 报警阈值 ×10 摄氏度 */\n    uint8_t  report_s;     /* 上报周期，秒 */\n    uint8_t  reserved[3];  /* 补到 12 字节，与 8 字节页对齐更好拆 */\n} Param_t;\n\nstatic Param_t s_param;        /* 内存里的“当前生效参数” */\nstatic uint8_t s_from_eeprom;  /* 1 = 来自 EEPROM，0 = 用的默认值 */\n\n/* ---------------- ③ 扫一遍总线：把所有应答的 7 位地址列出来 ------------- */\nvoid bus_scan_report(void)\n{\n    uint8_t found[16];\n    uint8_t n;\n    uint8_t i;\n\n    /* 100000 = 100kHz。24C02 别跑 400k（头文件 AT24C02_I2C_SPEED 已定 100k） */\n    SYS_I2C_Init(SYS_I2C_1, 100000UL);\n\n    /* Scan 内部会自己加锁；返回 0 就是“整条总线没人应答” */\n    n = SYS_I2C_Scan(SYS_I2C_1, found, 16U);\n    printf(\"I2C1 上找到 %u 个器件：\", (unsigned)n);\n    for (i = 0U; i < n; i++) {\n        printf(\"0x%02X \", (unsigned)found[i]);\n    }\n    printf(\"\\r\\n\");\n\n    /* 逐个点名：地址对不上时，这一段能立刻告诉“是谁不在” */\n    if (SYS_I2C_IsDeviceReady(SYS_I2C_1, BUS_EEPROM) == SYS_I2C_OK) {\n        printf(\"EEPROM  0x50 在线\\r\\n\");\n    } else {\n        printf(\"EEPROM  0x50 不在线，查上拉/地址脚/供电\\r\\n\");\n    }\n    if (SYS_I2C_IsDeviceReady(SYS_I2C_1, BUS_MPU6050) == SYS_I2C_OK) {\n        uint8_t who = 0U;\n        /* 通用姿势：先给寄存器号 0x75，再读回芯片 ID（应为 0x68） */\n        SYS_I2C_ReadByte(SYS_I2C_1, BUS_MPU6050, 0x75U, &who);\n        printf(\"MPU6050 在线，WHO_AM_I = 0x%02X\\r\\n\", (unsigned)who);\n    }\n}\n\n/* ---------------- ④ 参数组包：MAGIC + 版本 + 长度 + CRC16 ---------------- */\nstatic uint16_t param_crc(const uint8_t *hdr)\n{\n    /* 自己按 8 位片算一遍：CRC16-MODBUS 是寄存器版，\n     *   中断里想用就得换成这个查表/逐位版本，语义与 MODBUS_CRC16 一致 */\n    uint16_t crc = 0xFFFFU;\n    uint16_t k;\n    uint8_t  b;\n\n    for (k = 0U; k < 6U; k++) {\n        crc ^= (uint16_t)hdr[k];\n        for (b = 0U; b < 8U; b++) {\n            if ((crc & 0x0001U) != 0U) {\n                crc = (uint16_t)((crc >> 1) ^ 0xA001U);\n            } else {\n                crc = (uint16_t)(crc >> 1);\n            }\n        }\n    }\n    return crc;\n}\n\nstatic void param_build_header(uint8_t *hdr)\n{\n    hdr[0] = P25_MAGIC0;\n    hdr[1] = P25_MAGIC1;\n    hdr[2] = P25_MAGIC2;\n    hdr[3] = P25_MAGIC3;\n    hdr[4] = P25_VER;\n    hdr[5] = (uint8_t)sizeof(Param_t);\n}\n\n/* 存：头 8 字节 + 体 12 字节，正好各占一页，天然不会跨页回卷 */\nstatic uint8_t param_save(const Param_t *p)\n{\n    uint8_t  hdr[8];\n    uint8_t  body[sizeof(Param_t)];\n    uint16_t crc;\n\n    param_build_header(hdr);\n    memcpy(body, p, sizeof(Param_t));\n\n    /* CRC 只覆盖定长头 6 字节（MAGIC + 版本 + 长度） */\n    crc = param_crc(hdr);\n    hdr[6] = (uint8_t)(crc & 0xFFU);        /* 低字节在前 */\n    hdr[7] = (uint8_t)(crc >> 8);\n\n    /* 两笔写必须整体成功或整体失败：外层再包一次锁（WriteBytes 内部\n     * 各自已经加过锁，本项目是递归锁，同任务嵌套安全，不会自锁死） */\n    SYS_I2C_Lock(SYS_I2C_1);\n    if (AT24C02_WriteBytes(P25_ADDR_HDR, hdr, 8U) != 0U) {\n        SYS_I2C_Unlock(SYS_I2C_1);\n        return 1U;\n    }\n    if (AT24C02_WriteBytes(P25_ADDR_BODY, body, (uint16_t)sizeof(Param_t)) != 0U) {\n        SYS_I2C_Unlock(SYS_I2C_1);\n        return 1U;\n    }\n    SYS_I2C_Unlock(SYS_I2C_1);\n    return 0U;\n}\n\n/* 读：三项校验全过才采用；任何一项不过都回落默认值 */\nstatic uint8_t param_load(Param_t *out)\n{\n    uint8_t  hdr[8];\n    uint16_t crc_now;\n    uint16_t crc_stored;\n\n    if (AT24C02_ReadBytes(P25_ADDR_HDR, hdr, 8U) != 0U) return 0U;\n\n    /* ① MAGIC：新名字 AT24C02_IsMagicSet 语义是“魔数在不在”，正向好读。\n     *    旧名 AT24C02_IsBlank 的语义与参数名相反，极易写反导致每次上电\n     *    重灌默认参数、把用户设置冲掉，所以库里已经改名。 */\n    if ((hdr[0] != P25_MAGIC0) || (hdr[1] != P25_MAGIC1) ||\n        (hdr[2] != P25_MAGIC2) || (hdr[3] != P25_MAGIC3)) {\n        return 0U;\n    }\n    /* ② 版本 + 长度：结构体改过就别读老数据 */\n    if ((hdr[4] != P25_VER) || (hdr[5] != (uint8_t)sizeof(Param_t))) {\n        return 0U;\n    }\n    /* ③ CRC16：内容坏了就整份丢掉，绝不让半个结构体进业务 */\n    crc_stored = (uint16_t)(((uint16_t)hdr[7] << 8) | (uint16_t)hdr[6]);\n    crc_now    = param_crc(hdr);\n    if (crc_now != crc_stored) {\n        return 0U;\n    }\n    if (AT24C02_ReadBytes(P25_ADDR_BODY, (uint8_t *)out, (uint16_t)sizeof(Param_t)) != 0U) {\n        return 0U;\n    }\n    return 1U;\n}\n\nstatic void param_defaults(Param_t *p)\n{\n    p->kp_x100     = 125U;      /* 1.25 */\n    p->ki_x100     = 30U;       /* 0.30 */\n    p->kd_x100     = 5U;        /* 0.05 */\n    p->temp_alarm  = 600U;      /* 60.0 摄氏度 */\n    p->report_s    = 5U;        /* 每 5 秒上报一次 */\n    p->reserved[0] = 0U;\n    p->reserved[1] = 0U;\n    p->reserved[2] = 0U;\n}\n\n/* ---------------- ⑤ 开机一条链：读→校验→否则默认+回写 ---------------- */\nuint8_t param_init(void)\n{\n    /* AT24C02_Init 内部含约 10ms 等待（上电后 EEPROM 需要准备时间） */\n    if (AT24C02_Init(0U) != 0U) {\n        param_defaults(&s_param);\n        s_from_eeprom = 0U;\n        return 1U;                      /* 器件没应答，先用默认值跑 */\n    }\n\n    if (param_load(&s_param) != 0U) {\n        s_from_eeprom = 1U;\n        printf(\"参数从 EEPROM 读取成功\\r\\n\");\n    } else {\n        /* 空片 / 版本不符 / CRC 不过，都走这里：用默认值并回写一次，\n         * 这样下次上电就能读到一份合法的参数，而不是每次都回落。 */\n        param_defaults(&s_param);\n        s_from_eeprom = 0U;\n        if (param_save(&s_param) != 0U) {\n            printf(\"默认参数回写失败：查上拉/写周期/地址规划\\r\\n\");\n            return 2U;\n        }\n        printf(\"首次上电或参数损坏，已写入默认值\\r\\n\");\n    }\n    printf(\"Kp=%u.%02u Ki=%u.%02u Kd=%u.%02u 阈值=%u.%u 上报=%us\\r\\n\",\n           (unsigned)(s_param.kp_x100 / 100U), (unsigned)(s_param.kp_x100 % 100U),\n           (unsigned)(s_param.ki_x100 / 100U), (unsigned)(s_param.ki_x100 % 100U),\n           (unsigned)(s_param.kd_x100 / 100U), (unsigned)(s_param.kd_x100 % 100U),\n           (unsigned)(s_param.temp_alarm / 10U), (unsigned)(s_param.temp_alarm % 10U),\n           (unsigned)s_param.report_s);\n    return 0U;\n}\n\n/* ---------------- ⑥ 出错时怎么自救：先救总线，再重试一次 ---------------- */\nint bus_read_with_recovery(uint8_t addr7, uint8_t reg, uint8_t *out)\n{\n    int err = SYS_I2C_ReadByte(SYS_I2C_1, addr7, reg, out);\n\n    if (err == SYS_I2C_ERR_TIMEOUT) {\n        /* 超时 = 总线被某个从机拉死了。BusReset 发 9 个时钟 + STOP，\n         *   把从机的移位状态机踢回空闲，然后重新初始化本机 I2C。 */\n        SYS_I2C_BusReset(SYS_I2C_1);\n        err = SYS_I2C_ReadByte(SYS_I2C_1, addr7, reg, out);\n    } else if (err == SYS_I2C_ERR_ADDR) {\n        /* -3 无应答：另一种常见原因是“EEPROM 还在 5ms 写周期里”。\n         *   多笔连续写之间一定要让驱动把写周期等完（at24c02.c 用\n         *   IsDeviceReady 轮询 + delay_ms(5) 兜底做了这件事）。 */\n        printf(\"0x%02X 无应答：%s\\r\\n\", (unsigned)addr7, SYS_I2C_ErrStr(err));\n    }\n    return err;   /* 0 = OK；负值 = SYS_I2C_ERR_* */\n}\n",
 r:"上电后先看串口：bus_scan_report 打印出的地址列表里必须出现 0x50 和 0x68（外接 OLED/AHT10 接上时应再出现 0x3C / 0x38）；然后 param_init 返回 0 并在第一次打印“首次上电或参数损坏，已写入默认值”，第二次及以后（断电重启）打印“参数从 EEPROM 读取成功”，且 Kp/Ki/Kd 打印值与上次相同，这就证明参数真的跨过了断电。反向验证三件事：① 把 24C02 的 SDA 拔掉，Scan 返回 0、param_init 返回 1 并回落默认值；② 用调试器把参数体某个字节改坏（或故意把 P25_VER 改成 2），下次上电必然走“损坏”分支并重写默认值；③ 把 AT24C02_WriteBytes(P25_ADDR_BODY, ...) 手写成一个可能跨页的起始地址（比如 0x1C 起写 12 字节），观察参数头被回卷覆盖、CRC 立刻不过，这正是页写回卷的现场。",
 k:"I2C 总线 一条总线 多器件 挂多个器件 共享总线 7位地址 8位地址 左移 地址冲突 BMP280 BME280 0xD0 芯片ID 0x58 0x60 BH1750 0x23 0x5C CCS811 0x5A 0x5B SHT30 0x44 AHT10 0x38 MPU6050 0x68 SSD1306 0x3C 0x3D SA0 AT24C02 0x50 0x76 0x77 上拉 4.7k 开漏 共地 总线电容 400pF 100kHz 400kHz 快速模式 SYS_I2C_Init SYS_I2C_Scan SYS_I2C_IsDeviceReady SYS_I2C_WriteByte SYS_I2C_ReadByte SYS_I2C_WriteBytes SYS_I2C_ReadBytes SYS_I2C_WriteCmd SYS_I2C_ReadRaw SYS_I2C_WriteReg16 SYS_I2C_ReadReg16 SYS_I2C_BusReset SYS_I2C_Lock SYS_I2C_Unlock SYS_I2C_ErrStr 递归互斥量 递归锁 __get_IPS R 中断上下文 ISR 队列 信号量 错误码 ERR_PARAM -1 ERR_START -2 ERR_ADDR -3 ERR_DATA -4 ERR_TIMEOUT -5 ERR_BUS -6 9个时钟 时钟拉伸 EEPROM 24C02 256字节 页写 8字节页 跨页 回卷 绕回 写周期 5ms ACK轮询 IsDeviceReady 轮询 MAGIC 魔数 AT24C02_IsMagicSet AT24C02_IsBlank 改名 语义相反 W25QXX_IsBlank 版本 长度 CRC16 MODBUS 0xA001 0xFFFF 低字节在前 A/B 双份 轮换 掉电 原子写 写完再改标志 空片 全0xFF 默认参数 回写 AT24C02_Init AT24C02_WriteBytes AT24C02_ReadBytes AT24C02_WriteU16 AT24C02_WriteFloat AT24C02_WriteString AT24C02_Erase AT24C02_TOTAL_SIZE AT24C02_PAGE_SIZE AT24C02_WRITE_MS AT24C02_ADDR_MAGIC AT24C02_ADDR_PARAM AT24C02_ADDR_CALIB AT24C02_MAGIC_VALUE 参数保存 掉电保存 参数表 阈值 校准值 PID 系数 相关"}
"""

GUIDE_P25_I2C_EEPROM = r"""
/* ===================== ㉕ I2C 多器件与参数保存引导 ===================== */
{m:"引导", t:"guide", n:"🧭 ㉕ I2C 多器件与参数保存引导（一条总线接多个器件，含参数保存）",
 d:"从“一根线上能挂多少器件、地址怎么分”讲起，一路走到“参数掉电不丢”：先用 SYS_I2C_Scan 把总线上所有应答的地址列出来，再依次掌握单寄存器读写、只发命令、不发寄存器直接读、16 位寄存器这四种时序，然后死磕 AT24C02 的两条硬规矩（8 字节页、5ms 写周期）和最贵的一课（页写回卷会静默覆盖 MAGIC 区），最后落到 MAGIC + 版本 + 长度 + CRC16 的“信封式”参数保存、A/B 双份轮换抗掉电、以及多任务下的递归锁与中断禁入。",
 g:"STM32F407 · 板2 数据通信端 · I2C1（SCL = PB8 / SDA = PB9，板上 4.7k 上拉）· 100kHz · AT24C02(0x50) + MPU6050(0x68) + 外接 OLED(0x3C)/AHT10(0x38) · 对应 FWLIB 的 sys_i2c.c/.h + at24c02.c/.h",
 k:"I2C 引导 向导 教程 步骤 总线 多器件 共享总线 地址规划 7位地址 8位地址 上拉 4.7k 开漏 共地 电容 400pF 100kHz 400kHz SYS_I2C_Init SYS_I2C_Scan 扫描 点名 IsDeviceReady WriteByte ReadByte 先下指针 ReSTART WriteCmd ReadRaw BH1750 WriteReg16 ReadReg16 AT24C02 256字节 页写 8字节 跨页 回卷 写周期 5ms ACK轮询 MAGIC CRC16 MODBUS A/B 双份 掉电 参数保存 锁 递归互斥量 中断 ISR BusReset 9个时钟 排错 NACK -3 全0xFF 相关",
 e:"/* ============================================================\n *  ㉕ 引导 10 步的成品：一条 I2C1 总线 + 参数掉电保存\n *  平台：STM32F407 · 板2（数据通信端）\n *  总线：I2C1 SCL = PB8 / SDA = PB9（板上 4.7k 上拉，100kHz）\n *  器件：AT24C02(0x50) · MPU6050(0x68) · 外接 OLED(0x3C) / AHT10(0x38)\n * ============================================================ */\n#include \"stm32f4xx.h\"\n#include \"sys_i2c.h\"\n#include \"at24c02.h\"\n\n#include <string.h>\n\n/* ---------------- 地址规划（写进自己的笔记，别散落在代码里） ------------\n *  0x00 ~ 0x03   MAGIC 区（AT24C02_ADDR_MAGIC，值 0xA5）\n *  0x10 ~ 0x17   参数头：MAGIC4 + 版本1 + 长度1 + CRC16(2)\n *  0x18 ~ 0x23   参数体 Param_t（12 字节）\n *  0x40          A/B 轮换的“当前有效份”标志（0xA0 = A 有效 / 0xB0 = B 有效）\n *  0x80 ~ 0xEF   校准数据区\n * ============================================================ */\n#define P25_HDR_A     0x10U\n#define P25_BODY_A    0x18U\n#define P25_HDR_B     0x30U\n#define P25_BODY_B    0x38U\n#define P25_AB_FLAG   0x40U\n#define P25_FLAG_A    0xA0U\n#define P25_FLAG_B    0xB0U\n\ntypedef struct {\n    uint16_t kp_x100;\n    uint16_t ki_x100;\n    uint16_t kd_x100;\n    uint16_t temp_alarm;\n    uint8_t  report_s;\n    uint8_t  reserved[3];\n} Param_t;\n\nstatic Param_t s_param;\nstatic uint8_t s_slot;          /* 0 = 当前用 A 份，1 = 当前用 B 份 */\n/* 别在真代码里用变长数组拼 CRC 输入：MISRA 不喜欢，栈也不可控 */\nstatic uint8_t s_hdr_tmp[8];\n\nstatic void param_defaults(Param_t *p)\n{\n    p->kp_x100 = 125U;\n    p->ki_x100 = 30U;\n    p->kd_x100 = 5U;\n    p->temp_alarm = 600U;\n    p->report_s = 5U;\n    p->reserved[0] = 0U;\n    p->reserved[1] = 0U;\n    p->reserved[2] = 0U;\n}\n\n/* CRC16-MODBUS 放在数据后面：把 6 字节头和 12 字节体一起算进去。\n * 这就是“CRC 覆盖范围包含自身时整段再算一遍为 0”那个性质的用法。 */\nstatic uint16_t param_crc(const uint8_t *h, const uint8_t *b)\n{\n    uint16_t crc = 0xFFFFU;\n    uint16_t k;\n    uint8_t  bit;\n\n    for (k = 0U; k < 6U; k++) {\n        crc ^= (uint16_t)h[k];\n        for (bit = 0U; bit < 8U; bit++) {\n            crc = ((crc & 1U) != 0U) ? (uint16_t)((crc >> 1) ^ 0xA001U)\n                                     : (uint16_t)(crc >> 1);\n        }\n    }\n    for (k = 0U; k < (uint16_t)sizeof(Param_t); k++) {\n        crc ^= (uint16_t)b[k];\n        for (bit = 0U; bit < 8U; bit++) {\n            crc = ((crc & 1U) != 0U) ? (uint16_t)((crc >> 1) ^ 0xA001U)\n                                     : (uint16_t)(crc >> 1);\n        }\n    }\n    return crc;\n}\n\n/* ---------------- 写一份：头 8 字节一页 + 体 12 字节两页 ---------------- */\nstatic uint8_t param_write_slot(uint8_t hdr_addr, uint8_t body_addr, const Param_t *p)\n{\n    uint8_t  hdr[8];\n    uint8_t  body[sizeof(Param_t)];\n    uint16_t crc;\n\n    hdr[0] = 0x50U; hdr[1] = 0x32U; hdr[2] = 0x35U; hdr[3] = 0x41U;  /* \"P25A\" */\n    hdr[4] = 1U;                                /* 版本 */\n    hdr[5] = (uint8_t)sizeof(Param_t);          /* 长度 */\n    memcpy(body, p, sizeof(Param_t));\n    crc = param_crc(hdr, body);\n    hdr[6] = (uint8_t)(crc & 0xFFU);            /* 低字节在前 */\n    hdr[7] = (uint8_t)(crc >> 8);\n\n    /* 8 + 12 = 20 字节，但绝不能一次全写：0x10 起 8 字节正好第一页，\n     *   0x18 起 12 字节会跨页（0x18 页内偏移 0，8 字节后到 0x20 是\n     *   下一页，还剩 4 字节），必须交给 AT24C02_WriteBytes 自动分片。 */\n    if (AT24C02_WriteBytes(hdr_addr, hdr, 8U) != 0U)  return 1U;\n    if (AT24C02_WriteBytes(body_addr, body, (uint16_t)sizeof(Param_t)) != 0U) return 1U;\n    return 0U;\n}\n\n/* ---------------- 读一份：MAGIC + 版本 + 长度 + CRC 四关 ---------------- */\nstatic uint8_t param_read_slot(uint8_t hdr_addr, uint8_t body_addr, Param_t *out)\n{\n    uint8_t  hdr[8];\n    uint8_t  body[sizeof(Param_t)];\n    uint16_t crc_now, crc_stored;\n\n    if (AT24C02_ReadBytes(hdr_addr, hdr, 8U) != 0U) return 0U;\n    if ((hdr[0] != 0x50U) || (hdr[1] != 0x32U) ||\n        (hdr[2] != 0x35U) || (hdr[3] != 0x41U)) return 0U;\n    if ((hdr[4] != 1U) || (hdr[5] != (uint8_t)sizeof(Param_t))) return 0U;\n    if (AT24C02_ReadBytes(body_addr, body, (uint16_t)sizeof(Param_t)) != 0U) return 0U;\n\n    crc_stored = (uint16_t)(((uint16_t)hdr[7] << 8) | (uint16_t)hdr[6]);\n    crc_now    = param_crc(hdr, body);\n    if (crc_now != crc_stored) return 0U;\n\n    memcpy(out, body, sizeof(Param_t));\n    return 1U;\n}\n\n/* ---------------- 保存：先写另一份，再原子地改标志 ---------------- */\nuint8_t param_save(const Param_t *p)\n{\n    uint8_t next = (uint8_t)(s_slot ^ 1U);          /* 永远写“非当前”的那一份 */\n    uint8_t flag;\n\n    /* 外层锁：这一整段是“多笔连续事务”，中途被别的任务插进来就毁了。\n     *   sys_i2c 的每个公共入口内部也都加锁，本项目是递归锁，嵌套安全。 */\n    SYS_I2C_Lock(SYS_I2C_1);\n\n    if (next == 0U) {\n        if (param_write_slot(P25_HDR_A, P25_BODY_A, p) != 0U) {\n            SYS_I2C_Unlock(SYS_I2C_1);\n            return 1U;\n        }\n    } else {\n        if (param_write_slot(P25_HDR_B, P25_BODY_B, p) != 0U) {\n            SYS_I2C_Unlock(SYS_I2C_1);\n            return 1U;\n        }\n    }\n\n    /* 关键顺序：先把数据写完并确认，再改标志。\n     *   如果先改标志再写数据，掉电就会得到“标志指向一份没写完的数据”。\n     *   反之，最坏情况只是“标志仍指向旧副本”，旧副本完整，能正常启动。 */\n    flag = (next == 0U) ? P25_FLAG_A : P25_FLAG_B;\n    if (AT24C02_WriteByte(P25_AB_FLAG, flag) != 0U) {\n        SYS_I2C_Unlock(SYS_I2C_1);\n        return 2U;\n    }\n\n    SYS_I2C_Unlock(SYS_I2C_1);\n    s_slot = next;\n    return 0U;\n}\n\n/* ---------------- 加载：标志优先，标志不可信就两份都试 ---------------- */\nuint8_t param_load(void)\n{\n    uint8_t flag = 0U;\n    Param_t tmp;\n\n    /* 标志本身也可能坏（空片 0xFF / 写一半），所以它只是“优先提示”，\n     *   绝不能“标志说用 A 就无脑信 A”。真正的判据永远是那一份自己的 CRC。 */\n    if (AT24C02_ReadByte(P25_AB_FLAG, &flag) == 0U) {\n        if (flag == P25_FLAG_A) {\n            if (param_read_slot(P25_HDR_A, P25_BODY_A, &s_param) != 0U) { s_slot = 0U; return 0U; }\n        } else if (flag == P25_FLAG_B) {\n            if (param_read_slot(P25_HDR_B, P25_BODY_B, &s_param) != 0U) { s_slot = 1U; return 0U; }\n        }\n    }\n\n    /* 标志无效，或标志指向的那份 CRC 没过：两份都试一遍，谁过用谁。\n     * 这就是 A/B 轮换的全部价值，掉电最多只丢最后一次改动。 */\n    if (param_read_slot(P25_HDR_A, P25_BODY_A, &tmp) != 0U) {\n        memcpy(&s_param, &tmp, sizeof(Param_t));\n        s_slot = 0U;\n        return 0U;\n    }\n    if (param_read_slot(P25_HDR_B, P25_BODY_B, &tmp) != 0U) {\n        memcpy(&s_param, &tmp, sizeof(Param_t));\n        s_slot = 1U;\n        return 0U;\n    }\n    return 1U;      /* 两份都不可信：调用方接手写默认值 */\n}\n\n/* ---------------- 开机自检：扫描 + 加载 ---------------- */\nuint8_t i2c_boot_selfcheck(void)\n{\n    uint8_t found[16];\n    uint8_t n, i;\n\n    SYS_I2C_Init(SYS_I2C_1, 100000UL);\n    n = SYS_I2C_Scan(SYS_I2C_1, found, 16U);\n    printf(\"I2C1 应答 %u 个：\", (unsigned)n);\n    for (i = 0U; i < n; i++) printf(\"0x%02X \", (unsigned)found[i]);\n    printf(\"\\r\\n\");\n\n    if (AT24C02_Init(0U) != 0U) return 1U;          /* 0x50 没应答 */\n\n    /* 用驱动自己的魔数接口判“空片”，新语义：1 = 魔数在 = 存过。\n     * 旧名 AT24C02_IsBlank 的返回值含义与参数名相反，已废弃改名。 */\n    if (AT24C02_IsMagicSet(AT24C02_ADDR_MAGIC, AT24C02_MAGIC_VALUE) == 0U) {\n        param_defaults(&s_param);\n        s_slot = 1U;                                 /* 让第一次保存去写 A 份 */\n        (void)param_save(&s_param);\n        (void)AT24C02_WriteByte(AT24C02_ADDR_MAGIC, AT24C02_MAGIC_VALUE);\n        printf(\"空片：已写入默认参数并打上魔数标记\\r\\n\");\n        return 0U;\n    }\n\n    if (param_load() != 0U) {\n        param_defaults(&s_param);\n        (void)param_save(&s_param);\n        printf(\"两份参数都不可信：回落默认值并重写\\r\\n\");\n        return 2U;\n    }\n    printf(\"参数加载成功：Kp=%u.%02u 阈值=%u.%u 上报=%us\\r\\n\",\n           (unsigned)(s_param.kp_x100 / 100U), (unsigned)(s_param.kp_x100 % 100U),\n           (unsigned)(s_param.temp_alarm / 10U), (unsigned)(s_param.temp_alarm % 10U),\n           (unsigned)s_param.report_s);\n    return 0U;\n}\n",
 f:[
  [
   "一条总线上能挂多少器件，地址又是怎么分的",
   "I2C 的设计哲学是“两根线、地址寻址、共享总线”：主机只占用 SDA（数据）和 SCL（时钟），从机靠7 位地址被点名，所以理论上一条总线上可以并行挂到一百多个器件。本项目板2 的 I2C1（SCL = PB8 / SDA = PB9）上就同时挂着板载 AT24C02（0x50）、板载 MPU6050（0x68），以及从排针接出去的外接 OLED（0x3C）、AHT10（0x38）、SHT30（0x44），它们互不干扰，因为地址不同。\n\n所以“挂不上器件”这件事，真正的原因几乎永远是下面三条之一，而不是数量：\n\n① 地址撞车。 每个器件的地址由固定前缀 + 可配置低位（A0/A1/A2 或 SA0/AD0）组成。撞了就彻底没办法用地址区分，最典型的例子是 BMP280 和 BME280 用的是同一组地址（0x76 / 0x77），接线完全一样，只能靠读寄存器 0xD0 的芯片 ID（BMP280 = 0x58、BME280 = 0x60）来区分自己手里是哪一个。同理 SSD1306 的 0x3C/0x3D 由 SA0 脚决定，BH1750 的 0x23/0x5C 由 ADDR 脚决定。\n\n② 7 位地址被写成了 8 位。 数据手册里常给“写地址 0xD0 / 读地址 0xD1”，那是把 7 位地址左移一位并补上读写位的结果。本项目函数里的 addr7 参数一律是 7 位，所以 0xD0 要右移一位变成 0x68 才能传。传错的表现是稳定的 NACK（SYS_I2C_ERR_ADDR = -3），不会时好时坏。\n\n③ 电气条件不成立。 上拉缺失、没共地、总线电容过大，这三条属于下一步的内容，但现象同样是 NACK 或偶发乱码。",
   "① 把本项目板2 的地址总表抄下来（24C02 = 0x50、MPU6050 = 0x68、AHT10 = 0x38、SHT30 = 0x44、SSD1306 = 0x3C/0x3D、BMP280 = 0x76/0x77、BH1750 = 0x23/0x5C、CCS811 = 0x5A/0x5B）；② 为每个器件标出“地址低位由哪个脚决定”；③ 想清楚如果同时要 BMP280 和 BME280 该怎么办（答案是没法办，只能分时接）。",
   "/* 本项目 I2C1 的地址分配（7 位，直接传进 SYS_I2C_xxx）\n *   0x50  AT24C02    板载 EEPROM，A2A1A0 全接地\n *   0x68  MPU6050    板载六轴，AD0 = 0\n *   0x3C  SSD1306    外接 OLED（SA0 = 0 时；接 3.3V 变 0x3D）\n *   0x38  AHT10      外接温湿度\n *   0x44  SHT30      外接温湿度\n *\n * 换器件/换地址脚后，先想清楚“新地址是多少”，再改代码：\n *   #define SYS_I2C_ADDR_24C02  0x50\n *   #define SYS_I2C_ADDR_MPU6050 0x68\n *\n * 手册给 0xD0 / 0xD1 这类 8 位地址时：\n *   addr7 = 0xD0 >> 1 = 0x68;\n */\n\n/* 同名地址、只能靠芯片 ID 区分的例子（BMP280 / BME280）： */\n#define BMP280_ADDR_PRIMARY  0x76\n#define BME280_ID            0x60    /* 读 0xD0 == 0x60 就是 BME280 */\n#define BMP280_ID            0x58    /* 读 0xD0 == 0x58 就是 BMP280 */",
   "能不看笔记写出至少 6 个器件的 7 位地址，并说清 0xD0 与 0x68 的关系（右移一位）。\n能解释“为什么地址冲突比数量超限更常见”，并知道 BMP280/BME280 的同址问题只能靠读 0xD0 区分。",
   "把 8 位地址直接传进 addr7：必然 NACK，而且会怀疑接线，白折腾半天。\n以为“一条总线只能挂一个器件”：I2C 本来就是多主多从总线，挂一堆是常态。\n以为“地址不同的两个器件可以随便同时用”：软件上可以，但总线上每个器件都会看到每一笔事务的开头，地址不匹配才放手，所以一个器件把 SDA 拉死，整条总线全挂。\n忘了 A0/A1/A2 不是“随便接地就行”：它们决定了地址低位，两块同型号模块如果都接地就会撞车，要错开。",
   "SYS_I2C_ADDR_24C02 SYS_I2C_ADDR_MPU6050 SYS_I2C_ADDR_AHT10 SYS_I2C_ADDR_SHT30 SYS_I2C_ADDR_SSD1306 SYS_I2C_1 SYS_I2C_COUNT SysI2cId_t 0x76 0x77 0x23 0x5C 0x5A 0x5B 0xD0 WHO_AM_I"
  ],
  [
   "硬件三件事：4.7k 上拉、必须共地、总线电容别超 400pF",
   "I2C 的电气形态是开漏输出 + 外部上拉，这一点决定了它的所有硬件规矩。\n\n为什么是开漏？ 因为多器件共享同一根线，如果谁都用推挽输出，一个拉高一个拉低就是电源对地短路。开漏意味着每个器件只能把线拉低，谁也拉不高，所以“恢复高电平”这件事必须由上拉电阻来做。这就带来第一条硬规矩：SDA 和 SCL 各要一只约 4.7k 的电阻上拉到 3.3V（本项目板载总线已经焊好，接外接模块时要确认模块上有没有、或者接上以后会不会形成“两个上拉并联”把等效阻值降到 2.3k 左右）。\n\n上拉阻值怎么定？ 它是一对矛盾：阻值太大，线与线的寄生电容充电慢，上升沿变缓，400kHz 快速模式下波形根本爬不到高电平就被下一个时钟打断；阻值太小，从机拉低时要灌入过大电流，超过器件规格（标准模式 3mA、快速模式 6mA）。4.7k 在 3.3V 下灌电流约 0.7mA，是个各方面都安全的通用值。\n\n总线电容上限约 400pF。 这是 I2C 规范的硬指标，因为电容越大上升沿越慢，上拉电阻再小也救不回来。一根杜邦线约 20~50pF，所以线拉到一两米就非常危险了。工程上的对策依次是：缩短走线 → 降速到 100kHz → 用屏蔽线/双绞线 → 上 I2C 中继器或隔离器。本项目板载部分走线很短，100kHz 下毫无压力；外接模块走线超过 30cm 就该考虑降到 100kHz。\n\n必须共地。 和所有“两根信号线”的总线一样，I2C 的“高/低”是相对双方共同的地参考的。不共地时判据漂移，现象是“扫得到地址但数据全是垃圾”或者“时通时不通”，这种问题最容易被误判成软件 bug。",
   "① 用万用表在断电状态下量 SDA 对 3.3V、SCL 对 3.3V 的电阻，应该都在 4.7k 附近（本项目板载如此）；② 量的同时对地量，不应该短路；③ 上电后用示波器看 SCL 波形，100kHz 下上升沿应该明显快于下降沿（开漏的典型特征），如果上升沿是明显的圆弧且爬得慢，就是上拉太弱或电容太大，先降速到 100kHz 试试；④ 外接模块的 GND 必须和主板 GND 用短线直连。",
   "/* 接线与电气检查表（板2 I2C1）\n *   PB8  ->  SCL   板上已有 4.7k 上拉到 3.3V\n *   PB9  <->  SDA   板上已有 4.7k 上拉到 3.3V\n *   3.3V ->  各模块 VCC（外接模块就近并 100nF 去耦）\n *   GND  <-> 各模块 GND   必须共地\n *\n * 开漏形态决定了三件事：\n *   ① 任何器件只能拉低，拉高靠上拉电阻；\n *   ② 两个器件同时拉低是“线与”，不是短路；\n *   ③ 一个器件把线钉死为低，整条总线全挂，这时用\n *      SYS_I2C_BusReset(总线) 发 9 个时钟 + STOP 把它踢出来。\n *\n * 速率与电容：\n *   标准模式 100kHz / 快速模式 400kHz\n *   总线电容上限约 400pF（杜邦线 20~50pF/根，线长要克制）\n *   本项目 24C02 用 100kHz（AT24C02_I2C_SPEED = 100000UL）\n */",
   "示波器上 SCL 上升沿明显快于下降沿；把总线速率从 100kHz 提到 400kHz 波形仍然干净（说明上拉和电容都合格）。\n反向验证：故意把 SDA 的上拉电阻断开，SYS_I2C_IsDeviceReady 会返回 SYS_I2C_ERR_START（-2），起始条件都发不出去，这个错误码几乎就是“上拉没了”的专用提示。",
   "以为“模块自带 4.7k 上拉，板载也有 4.7k，两个一起用更好”，两个并联变成 2.3k，灌电流翻倍，短距离下通常没事，但已经偏离规范，长线或低压时会出问题。\n用 10k 上拉还想跑 400kHz：上升沿爬不起来，现象是随机 NACK、随机数据错。\n不共地：现象是“地址扫得到、数据全乱”，软件怎么查都查不出来。\n线拉太长还硬跑 400kHz：降速到 100kHz 往往立刻就好，这不是“凑合”，是工程上的正确取舍。\n忽略 BusReset：从机被干扰后可能停在“以为自己还在收字节”的状态，把 SDA 一直拉低，不救总线，后面每一笔事务都超时。",
   "SYS_I2C_BusReset SYS_I2C_Init SYS_I2C_IsDeviceReady SYS_I2C_ERR_START SYS_I2C_TIMEOUT SYS_I2C_1 SYS_I2C1_SCL_PIN SYS_I2C1_SDA_PIN SYS_I2C_BUS_DELAY OpenDrain"
  ],
  [
   "初始化 + 扫描：把总线上所有应答的地址一次性列出来",
   "现在把总线拉起来，然后干一件“性价比最高”的验收动作：扫描。\n\n`SYS_I2C_Init(SYS_I2C_1, 100000)` 做三件事：开 I2C 和外设 GPIO 的时钟、把 SCL/SDA 配成开漏复用、按 speed 算出 CCR/TRISE 寄存器（100kHz 对应的值）。它幂等，重复调用只是重新配置。\n\n`SYS_I2C_Scan(bus, found, max)` 是这一步的主角：内部从 0x08 扫到 0x77（避开 I2C 保留地址），每个地址发一次 START + 地址 + 读位，收到 ACK 就把这个 7 位地址记进 found[]，返回找到的个数。说明里明确写了“found[] 写入 7 位地址，最多 max 个，可传 0 只要计数”。\n\n为什么它这么有用？因为 I2C 是共享总线：如果点名去找某个器件，它不在也只知道“它不在”；而扫描能一次告诉总线上到底有谁，地址接错（比如 A0 忘记接地）、模块没供电、焊接虚焊、上拉缺失，全都会在扫描结果里露出来。本项目实际接线应该扫出 0x50 和 0x68，接上外接屏后还会多一个 0x3C。\n\n扫描配合点名效果最好：先扫出全名单，再用 `SYS_I2C_IsDeviceReady(bus, addr7)` 对地址表里的每个器件确认一次（它返回 SYS_I2C_OK = 0 表示在线，SYS_I2C_ERR_ADDR = -3 表示不在线）。\n\n一个实现细节：Scan 内部自己会加锁，本项目每个公共入口都先锁总线、调内部实现、再解锁。所以不要在一个循环里持着外层锁去反复调 Scan，那会让别的任务干等整个扫描过程（扫描要发上百次 START，几百微秒到几毫秒量级）。",
   "① 用 SYS_I2C_Init(SYS_I2C_1, 100000UL) 初始化；② 用 SYS_I2C_Scan 把结果打印出来，和地址表逐项对照；③ 对地址表里的每个器件用 SYS_I2C_IsDeviceReady 点名确认；④ 把这一整套放进开机自检，以后每次上电都能看到“谁在线”。",
   "/* 扫描 + 点名：I2C 排障的第一把钥匙 */\nvoid bus_scan_report(void)\n{\n    uint8_t found[16];\n    uint8_t n, i;\n\n    SYS_I2C_Init(SYS_I2C_1, 100000UL);      /* 100kHz */\n\n    n = SYS_I2C_Scan(SYS_I2C_1, found, 16U);\n    printf(\"I2C1 应答 %u 个：\", (unsigned)n);\n    for (i = 0U; i < n; i++) {\n        printf(\"0x%02X \", (unsigned)found[i]);\n    }\n    printf(\"\\r\\n\");\n\n    /* 点名：错误码直接告诉卡在哪一步 */\n    if (SYS_I2C_IsDeviceReady(SYS_I2C_1, SYS_I2C_ADDR_24C02) != SYS_I2C_OK) {\n        printf(\"EEPROM 0x50 没应答，%s\\r\\n\",\n               SYS_I2C_ErrStr(SYS_I2C_ERR_ADDR));\n    }\n    if (SYS_I2C_IsDeviceReady(SYS_I2C_1, SYS_I2C_ADDR_MPU6050) == SYS_I2C_OK) {\n        uint8_t who = 0U;\n        SYS_I2C_ReadByte(SYS_I2C_1, SYS_I2C_ADDR_MPU6050, 0x75U, &who);\n        printf(\"MPU6050 在线，WHO_AM_I = 0x%02X\\r\\n\", (unsigned)who);\n    }\n}",
   "串口打印出的地址列表里必须有 0x50 和 0x68（接了外接屏还会多 0x3C）。\n反向验证：把 24C02 的 SDA 从总线上断开，Scan 返回的个数少 1、0x50 消失，IsDeviceReady 返回 -3；再把 SDA 接回去，一切恢复，说明扫描确实是活的判据，而不是碰巧。",
   "以为 Scan 能测出“器件工作正常”：它只证明地址有 ACK，不证明寄存器读得对。扫到地址之后还要真的读一个已知寄存器（比如 MPU6050 的 0x75）才叫验证。\n忘了先调 SYS_I2C_Init：总线时钟没开，扫描全 0，会怀疑板子坏了。\n持着 SYS_I2C_Lock 去循环调 Scan：递归锁同任务嵌套不会死锁，但别的任务会一直等整个扫描跑完，实时性直接崩。\n看到 NACK 就改代码：先看 SYS_I2C_ErrStr(err) 的中文提示，-2 是起始条件（上拉/总线忙），-3 是地址（地址错/器件没上电），-4 是数据阶段（寄存器号不对），-5 是超时（总线被拉死，试 BusReset）。错误码已经把方向指出来了。",
   "SYS_I2C_Init SYS_I2C_Scan SYS_I2C_IsDeviceReady SYS_I2C_ErrStr SYS_I2C_ERR_ADDR SYS_I2C_ERR_START SYS_I2C_ERR_DATA SYS_I2C_ERR_TIMEOUT SYS_I2C_ERR_BUS SYS_I2C_OK SYS_I2C_1"
  ],
  [
   "单寄存器读写：WriteByte / ReadByte 是九成器件的通用姿势",
   "I2C 器件的主流形态是寄存器型：每个功能对应一个 8 位寄存器号，读写要“先告诉它哪个寄存器”。sys_i2c 把这件事拆成两个入口。\n\n写：`SYS_I2C_WriteByte(bus, addr7, reg, data)`，时序是 `START → 器件地址+W → ACK → 寄存器号 → ACK → 数据 → ACK → STOP`。很直白。\n\n读：`SYS_I2C_ReadByte(bus, addr7, reg, out)`，时序是 `START → 器件地址+W → ACK → 寄存器号 → ACK → ReSTART → 器件地址+R → ACK → 数据 → NACK → STOP`。为什么读也要先写一次？ 因为从机内部有一个“当前寄存器指针”，必须先用一次写事务把指针拨到目标寄存器，再用一次读事务把数据取出来。中间那一下 ReSTART（重复起始条件） 而不是 STOP + START，是 I2C 规范里的标准动作，中间若发 STOP，别的器件可能抢到总线，指针就变了。\n\n驱动内部帮处理的细节：收最后一个字节时主机要发 NACK 再发 STOP（告诉从机“我不需要更多了”）；每一步都有超时封顶（SYS_I2C_TIMEOUT = 2000000UL 次循环），卡死就返回错误码而不是死等。\n\n报告错误码是这套 API 的价值所在：`SYS_I2C_ERR_START = -2` 说明起始条件都发不出去（上拉缺失/总线忙），`SYS_I2C_ERR_ADDR = -3` 说明器件地址没人应答（地址错/没供电/还在写周期），`SYS_I2C_ERR_DATA = -4` 说明地址应了但数据阶段被 NACK（寄存器号不对，比如该器件没有有这个寄存器），`SYS_I2C_ERR_TIMEOUT = -5` 说明等标志超时（总线被拉死，试 BusReset）。-2/-3/-4 三个码把“硬件接线 / 器件地址 / 寄存器号”三件事分开了，这是排查效率的关键。",
   "① 挑一个已知寄存器的器件做实验：MPU6050 的 WHO_AM_I 在 0x75，读出来应该是 0x68；② 先 WriteByte 一个确定的值到某个可写可读的寄存器（比如 PWR_MGMT_1 = 0x6B），再 ReadByte 读回来比对；③ 故意把寄存器号改成 0xFF（多半不存在），观察错误码是否变成 -4，体会“数据阶段 NACK”和“地址 NACK”的区别。",
   "/* 单寄存器读写 + 错误码分流 */\nvoid reg_rw_demo(void)\n{\n    uint8_t who = 0U;\n    uint8_t back = 0U;\n    int     err;\n\n    /* ① 读 WHO_AM_I（只读寄存器，0x75），期望 0x68 */\n    err = SYS_I2C_ReadByte(SYS_I2C_1, SYS_I2C_ADDR_MPU6050, 0x75U, &who);\n    if (err != SYS_I2C_OK) {\n        printf(\"读 WHO_AM_I 失败：%s\\r\\n\", SYS_I2C_ErrStr(err));\n        return;\n    }\n    printf(\"WHO_AM_I = 0x%02X（应 0x68）\\r\\n\", (unsigned)who);\n\n    /* ② 写 PWR_MGMT_1（0x6B）解除休眠，再读回来比对 */\n    err = SYS_I2C_WriteByte(SYS_I2C_1, SYS_I2C_ADDR_MPU6050, 0x6BU, 0x00U);\n    if (err != SYS_I2C_OK) {\n        printf(\"写 PWR_MGMT_1 失败：%s\\r\\n\", SYS_I2C_ErrStr(err));\n        return;\n    }\n    err = SYS_I2C_ReadByte(SYS_I2C_1, SYS_I2C_ADDR_MPU6050, 0x6BU, &back);\n    if ((err != SYS_I2C_OK) || (back != 0x00U)) {\n        printf(\"写回不一致：err=%d back=0x%02X\\r\\n\", err, (unsigned)back);\n    }\n}",
   "打印出 WHO_AM_I = 0x68；写完 PWR_MGMT_1 = 0x00 再读回，值是 0x00（有些寄存器有保留位，可能读回不是完全等于写入值，这属于正常现象，要看手册的位定义）。\n反向验证：把 0x75 改成 0xFF，观察错误码从 0 变成 -4（数据阶段 NACK）而不是 -3，这一下就把“寄存器号错”和“器件地址错”区分开了。",
   "以为读寄存器不需要先写寄存器号：那样读到的是“上一次指针停留的位置”，数据看着像随机值。\n把 ReSTART 当成“两次独立事务”：中间一发 STOP，别的任务/器件就可能插进来，指针被改掉，读回脏数据。这也是为什么锁的粒度是“一次完整事务”而不是单字节。\n写入后立刻读回：有些器件（EEPROM 最典型）写完需要内部处理时间，这时读回会拿到旧值或 NACK。\n忽略返回码：一次 NACK 之后的后续操作往往全都失败，不对第一个错误立刻处理，日志会全是噪声。\n寄存器有保留位：写进去再读回来不等于原值，这是正常的，别拿着“写回不一致”去查总线。",
   "SYS_I2C_WriteByte SYS_I2C_ReadByte SYS_I2C_ErrStr SYS_I2C_OK SYS_I2C_ERR_START SYS_I2C_ERR_ADDR SYS_I2C_ERR_DATA SYS_I2C_ERR_TIMEOUT SYS_I2C_TIMEOUT 0x75 WHO_AM_I 0x6B PWR_MGMT_1 ReSTART 重复起始条件 ACK NACK"
  ],
  [
   "两种特殊时序：只发命令（WriteCmd）和不发寄存器直接读（ReadRaw）",
   "寄存器型器件是主流，但不是全部。有两类“时序不一样”的器件，如果不专门提供入口，就只能去改驱动。\n\n第一类：只接受一个命令字节的器件。 典型代表是 BH1750 光照传感器，它没有寄存器号概念，发的那个字节本身就是命令：0x01 = 上电、0x07 = 复位、0x10 = 连续 H 分辨率模式。时序是 `START → 器件地址+W → ACK → 命令字节 → ACK → STOP`，没有有“寄存器号”这一层。这就要用 `SYS_I2C_WriteCmd(bus, addr7, cmd)`。\n\n第二类：读数据前不需要拨指针的器件。 BH1750 进入连续测量模式之后，直接读它就会吐出 2 字节的光照值（高字节在前），不需要先写寄存器号。这就要用 `SYS_I2C_ReadRaw(bus, addr7, buf, len)`，它的时序是 `START → 器件地址+R → ACK → 数据... → NACK → STOP`。\n\n这一步最重要的是那个“问题”本身。 很多人看到 WriteCmd 会想：“不就发一个字节吗？我用 `SYS_I2C_WriteBytes(bus, addr7, 0, NULL, 0)` 不就行了？”，不行，而且是静默失败。sys_i2c.c 的 WriteBytes 一开头就判 `buf == 0 || len == 0` 并直接返回 SYS_I2C_ERR_PARAM（-1），一个字节都没发出去。看到的是“参数非法”，会自然而然地去查自己的参数写法，而不会想到“命令压根没发”；如果这个返回值又被忽略（很多人不看返回值），现象就变成“传感器没反应”，最后怀疑是模块坏了。头文件专门用一段注释点出这件事：“只发命令、不发数据”的写必须用 SYS_I2C_WriteCmd()，不能用 WriteBytes(..., NULL, 0)。\n\n顺带说：`len == 0` 也被一口回绝，是因为“长度 0 的写”在语义上就是“什么都不做”，让它返回成功反而更危险，调用方会以为命令发出去了。API 选择在这里表达的是“宁可报错，不可静默”。",
   "① 拿一块 BH1750（地址 0x23 或 0x5C，由 ADDR 脚决定）接上 I2C1；② 用它走完整流程：WriteCmd(0x01) 上电 → WriteCmd(0x10) 进连续 H 分辨率 → 等约 180ms → ReadRaw 读 2 字节 → 换算 lux = 原始值 / 1.2；③ 故意改写成 WriteBytes(bus, 0x23, 0, NULL, 0)，观察返回值是 -1（SYS_I2C_ERR_PARAM）且传感器毫无反应，把这个问题亲手踩一次，以后就不会忘。",
   "/* 只发命令 + 不发寄存器直接读：BH1750 光照传感器 */\n#define BH1750_ADDR      0x23U      /* ADDR 接 GND；接 VCC 变 0x5C */\n#define BH1750_POWER_ON  0x01U\n#define BH1750_CONT_H    0x10U      /* 连续 H 分辨率，1lx 精度 */\n\nint bh1750_read_lux(float *lux)\n{\n    uint8_t raw[2];\n    int     err;\n    uint16_t raw16;\n\n    /* ① 只发命令：必须用 WriteCmd，不能用 WriteBytes(..., NULL, 0) */\n    err = SYS_I2C_WriteCmd(SYS_I2C_1, BH1750_ADDR, BH1750_POWER_ON);\n    if (err != SYS_I2C_OK) return err;\n\n    err = SYS_I2C_WriteCmd(SYS_I2C_1, BH1750_ADDR, BH1750_CONT_H);\n    if (err != SYS_I2C_OK) return err;\n\n    /* ② 连续 H 分辨率模式一次测量最长 180ms，等够了再读 */\n    delay_ms(180);\n\n    /* ③ 不发寄存器号直接读 2 字节（高字节在前） */\n    err = SYS_I2C_ReadRaw(SYS_I2C_1, BH1750_ADDR, raw, 2U);\n    if (err != SYS_I2C_OK) return err;\n\n    raw16 = (uint16_t)(((uint16_t)raw[0] << 8) | (uint16_t)raw[1]);\n    *lux  = (float)raw16 / 1.2f;    /* 手册给的换算关系 */\n    return SYS_I2C_OK;\n}\n\n/* 反面教材（不要这么写）：\n *   SYS_I2C_WriteBytes(SYS_I2C_1, 0x23, 0, NULL, 0);\n *   源码判 buf == 0 || len == 0 → 直接返回 SYS_I2C_ERR_PARAM(-1)，\n *   字节一个都没发出去，却很容易被当成“器件坏了”。 */",
   "光照变化时 lux 值单调跟随（手遮住传感器数值骤降、拿开骤升）。\n反向验证：把 WriteCmd 换成 WriteBytes(..., NULL, 0)，返回值立刻变成 -1，且 lux 值保持不变，证明命令确实没发出去。再做一次“不发寄存器直接读”的对照：如果错误地用 ReadBytes（会先发一个寄存器号 0x00），BH1750 会把那个字节当成新命令，读到的东西就不对了。",
   "用 WriteBytes(..., NULL, 0) 发命令：静默失败（-1），而且很多人不看返回值。\n用 WriteBytes(..., cmd, ...) 代替 WriteCmd：会多出一个“寄存器号”字节，BH1750 会把它当命令执行，比如只想发 0x10，实际发出去的是 `0x10` 当寄存器号、后面还有数据，行为完全错乱。\n忘记测量时间：BH1750 连续 H 分辨率一次测量最长 180ms，读太快会拿到上一次的值或者 0。\n把 ReadRaw 用在寄存器型器件上：不发寄存器号，指针停留在上次位置，读回的是错数据。注释里给的两个入口是按器件类型分的，别混用。\n忽略 BH1750 的 ADDR 脚：接 GND 是 0x23，接 VCC 是 0x5C，扫不到就先去查这个脚。",
   "SYS_I2C_WriteCmd SYS_I2C_ReadRaw SYS_I2C_WriteBytes SYS_I2C_ReadBytes SYS_I2C_ERR_PARAM 0x23 0x5C BH1750 BH1750_POWER_ON BH1750_CONT_H lux 180ms delay_ms"
  ],
  [
   "16 位寄存器器件：WriteReg16 / ReadReg16",
   "前面所有 API 的 reg 参数都是 `uint8_t`，一个字节的寄存器号，最多寻址 256 个寄存器。这对 24C02（总共 256 字节）、MPU6050（寄存器号 ≤ 0x75）、AHT10 这类器件完全够用。但有一类器件内部地址空间超过 256：大容量 EEPROM（24C32 = 4K 字节、24C64 = 8K 字节）、某些大寄存器空间的传感器。它们需要两个字节的寄存器号。\n\n这就是 `SYS_I2C_WriteReg16(id, addr7, reg, buf, len)` 和 `SYS_I2C_ReadReg16(id, addr7, reg, buf, len)` 存在的原因：参数里的 `reg` 是 `uint16_t`，函数内部把它拆成高字节在前、低字节在后两个字节发出去（这是 24C32/24C64 这类器件的约定）。\n\n不能自己用 WriteBytes 拼接的原因： 当然可以，但那样就把“高字节在前”这个器件级约定写进了业务代码里，换器件、换驱动、别人接手，都要重新去猜顺序。库把它收进函数名里，是在表达“这是器件约定的地址宽度，不是业务逻辑”。\n\n本项目为什么用不上： AT24C02 总共只有 256 字节，地址就是 8 位，用 `AT24C02_WriteBytes`（内部走 `SYS_I2C_WriteBytes`，reg 是 uint8_t）才是对的。头文件里也把这件事说清楚了：24C02 的“寄存器地址”就是 EEPROM 内部字节地址，只有 8 位。\n\n这里有个很容易踩的迁移问题：把 24C02 的代码原样移植到 24C64 上，地址仍然是 uint8_t，那么 > 255 的地址永远访问不到。代码不报错、前 256 字节读写都正常，于是会以为“芯片是好的，只是后半片没接”，实际上后半片就在那儿，地址宽度不够。这类“自洽的错”最难查，唯一办法是知道器件手册说的地址宽度是几位。",
   "① 查手上 EEPROM 的手册，确认地址宽度：24C02/04/08/16 是 8 位（256/512/1K/2K 字节），24C32/64 及以上是 16 位；② 用 24C02 时走 AT24C02_WriteBytes 这一套（8 位地址）；③ 如果将来换 24C64，把驱动里的写读调用换成 SYS_I2C_WriteReg16 / ReadReg16，并确认 reg 传的是 16 位地址（高字节在前由库负责）。",
   "/* 地址宽度对照：选错 API 的后果 */\n/*  24C02  256 字节   地址 8 位   → AT24C02_WriteBytes / SYS_I2C_WriteByte\n *  24C04  512 字节   地址 8 位 + 页选择位（复用器件地址低位）\n *  24C08  1K 字节    同上，A2/A1 被拿去做页选择\n *  24C16  2K 字节    同上，A2/A1/A0 全被拿走\n *  24C32  4K 字节    地址 16 位   → SYS_I2C_WriteReg16 / ReadReg16\n *  24C64  8K 字节    地址 16 位   → 同上\n */\n\n/* 16 位地址器件的读写写法（以 24C64 为例，本项目 24C02 用不到） */\nint eeprom64_write(uint8_t addr7, uint16_t mem_addr,\n                   const uint8_t *buf, uint16_t len)\n{\n    /* reg 是 uint16_t：库内部按“高字节在前、低字节在后”发两个字节 */\n    return SYS_I2C_WriteReg16(SYS_I2C_1, addr7, mem_addr, buf, len);\n}\n\nint eeprom64_read(uint8_t addr7, uint16_t mem_addr,\n                  uint8_t *buf, uint16_t len)\n{\n    return SYS_I2C_ReadReg16(SYS_I2C_1, addr7, mem_addr, buf, len);\n}\n\n/* 24C02 用的是 8 位地址，别拿 Reg16 去套：\n *   24C02 的“寄存器号”就是它内部的字节地址（0x00~0xFF），\n *   多发的那个高字节会被它当数据吃掉。\n */",
   "用 24C02 时，AT24C02_WriteU16(0x20, 3000) 之后 AT24C02_ReadU16(0x20, &v) 能读回 3000，证明 8 位地址通路是通的。\n反向验证：假设手上真有一片 24C64，用 8 位地址的 API 去写地址 0x0100（256），写命令会成功返回 0，但读回来的还是 0x00 处的数据，地址高位被丢掉了。",
   "24C02 上用 Reg16：多发的高地址字节会被当成数据写进去，实际写入位置全错。\n大容量 EEPROM 上用 8 位地址 API：高地址位被丢弃，> 255 的区域永远访问不到，而且不报错。\n以为“地址宽度是软件自由度”：它是器件手册规定的，翻手册而不是猜。\n忽略 24C04/08/16 的“页选择位复用器件地址低位”：这几款器件的地址高位是从 A2/A1/A0 里借的，接线不同地址就不同，换型号时地址表必须重算。\n把 16 位地址的字节序搞反：24C32/64 是高字节在前，写反了会访问到完全不相干的位置。",
   "SYS_I2C_WriteReg16 SYS_I2C_ReadReg16 SYS_I2C_WriteBytes SYS_I2C_ReadBytes AT24C02_WriteU16 AT24C02_ReadU16 AT24C02_TOTAL_SIZE 24C02 24C32 24C64 高字节在前 地址宽度"
  ],
  [
   "AT24C02 的两条硬规矩：一次页写 8 字节、写完必须等 5ms",
   "走到 EEPROM 这里，先认清这块芯片的基本盘，再看两条会把人问题到怀疑人生的规矩。\n\n基本盘： AT24C02 = 2Kbit = 256 字节，7 位 I2C 地址 0x50（A2A1A0 全接地）。它按字节改写、单字节可擦写 100 万次，正好用来存“参数表”。本项目挂在 I2C1 上（SCL = PB8 / SDA = PB9），速率为 100kHz，头文件写得很直白：EEPROM 别跑 400k。\n\n硬规矩一：一次页写最多 8 字节，而且页内不能跨。 24C02 内部有 8 字节的页缓冲，一次写事务最多接收 8 个数据字节。这不只是“效率问题”，而是正确性问题（下一步专门讲回卷）。\n\n硬规矩二：写完要等约 5ms（最大 10ms）的写周期。 数据不是在 STOP 那一刻就落盘的，芯片收到数据后把它放进内部缓冲，然后在后台把它压进浮栅，这段时间它不对任何地址应答。所以：\n· 写完立刻发下一笔事务 → 从机不应答 → 拿到 SYS_I2C_ERR_ADDR = -3，看起来像“器件掉了”；\n· 写参数的耗时是“页数 × 5ms”，所以绝不能放在中断里，也不能放在一个高优先级任务的紧循环里。\n\n本项目怎么处理这个等待？ 教科书做法是死等 5ms。at24c02.c 用的是更好的办法，ACK 轮询：写完之后反复调用 `SYS_I2C_IsDeviceReady(AT24C02_I2C_ID, AT24C02_ADDR)` 探一下“它在不在”，一有 ACK 就说明写完了，通常 2~3ms 就返回，参数存得快近一倍。而且它留了两层保险：轮询最多 200 次，超了就 `delay_ms(AT24C02_WRITE_MS)` 兜底，万一芯片坏了永远不应答，也不会死在这里。\n\n这就是“读源码”的价值：如果不知道驱动已经做了 ACK 轮询，可能会在每次 WriteBytes 之后再自己 delay_ms(5)，参数保存时间凭空翻倍；或反向：自己写裸驱动时未等待，会持续收到 -3。",
   "① 用 AT24C02_WriteByte(0x10, 0x5A) 写一个字节，然后用示波器看 SDA/SCL，会看到 STOP 之后有一段时间总线是安静的（写周期）；② 在自己写的裸驱动里，故意在写完之后立刻发下一笔事务，观察返回 SYS_I2C_ERR_ADDR = -3；③ 算一下时间：写满 256 字节 = 32 页 × 5ms ≈ 160ms，而 AT24C02_Erase()（整片填 0xFF）头文件标注约 0.2 秒，对得上，说明页数×写周期的账算对了。",
   "/* 写周期的两种等法：驱动用的是右边那种（ACK 轮询） */\n\n/* ① 教科书做法：死等一个写周期 */\nstatic void wait_by_delay(void)\n{\n    delay_ms(AT24C02_WRITE_MS);        /* AT24C02_WRITE_MS = 5U */\n}\n\n/* ② 本项目 at24c02.c 的做法：ACK 轮询，写到哪算哪 */\nstatic void at24c02_wait_ready(void)\n{\n    uint32_t guard = 0;\n\n    /* 有 ACK 就说明内部写完了，通常 2~3ms 就能返回 */\n    while (guard++ < 200U) {\n        if (SYS_I2C_IsDeviceReady(AT24C02_I2C_ID, AT24C02_ADDR) == SYS_I2C_OK) {\n            return;\n        }\n    }\n    /* 兜底：芯片坏了永远不应答时，也不能死在这里 */\n    delay_ms(AT24C02_WRITE_MS);\n}\n\n/* 容量与页的账：256 字节 = 32 页 */\n/*   AT24C02_TOTAL_SIZE  256U\n *   AT24C02_PAGE_SIZE     8U\n *   AT24C02_WRITE_MS      5U\n *   整片写一遍 ≈ 32 × 5ms = 160ms（头文件说 Erase 约 0.2 秒）\n */",
   "用秒表/示波器量 AT24C02_WriteBytes(0x10, buf, 64) 的耗时：64 字节 = 8 页，应该在 20~40ms 量级（ACK 轮询比死等 40ms 快）。\n反向验证：把写周期等待去掉，连续写同一个地址两次，第二次大概率返回 -3；恢复等待后一切正常。再验证兜底：把 24C02 从总线拔掉，写函数会在 200 次轮询 + delay_ms(5) 之后返回错误，而不是死循环，程序还能跑。",
   "以为“发完 STOP 就写完了”：没等写周期就发下一笔，拿到 -3，然后去查接线和地址，白折腾。\n把参数保存放进中断或高优先级任务的紧循环：一次保存 20~40ms 起步，整个系统的实时性直接崩。\n自己在 WriteBytes 之后再 delay_ms(5)：驱动已经 ACK 轮询过了，白等，保存时间翻倍。\nEEPROM 跑 400kHz：器件手册支持，但本项目定为 100kHz（AT24C02_I2C_SPEED = 100000UL），而且高速下写周期的边界更容易踩。\n无脑死等：ACK 轮询比死等少等一半时间，写一整份参数（三页）的差距是可感知的。\n忘了兜底：芯片虚焊时死循环，看门狗都要被拖出来。",
   "AT24C02_Init AT24C02_WriteByte AT24C02_WriteBytes AT24C02_ReadBytes AT24C02_Erase AT24C02_IsOnline AT24C02_TOTAL_SIZE AT24C02_PAGE_SIZE AT24C02_WRITE_MS AT24C02_I2C_ID AT24C02_ADDR AT24C02_I2C_SPEED SYS_I2C_IsDeviceReady SYS_I2C_ERR_ADDR 写周期 ACK轮询 delay_ms"
  ],
  [
   "页写回卷：24C02 最贵的一课，它会把 MAGIC 区静默覆盖掉",
   "这是本卡最重要的一步，因为它是唯一一个“不报错、数据却已经被改掉”的问题。\n\n机制： 24C02 内部的字节地址是 8 位，其中低 3 位是页内指针（一页 8 字节），高 5 位是页号。在一次写事务里连发数据，芯片每收一个字节就把低 3 位加一；当低 3 位从 7 加回 0 时，它不进位到高 5 位，而是回卷到本页开头。\n\n后果： 设想参数头放在 0x00（MAGIC 区），想把参数体写到 0xF0 之后，写了一笔 `AT24C02_WriteBytes(250, buf, 10)`：\n```\n250 & 7 = 2  →  本页还剩 8 - 2 = 6 个字节（250..255）\n剩下 4 个字节（buf[6..9]）回卷写到 0..3\n```\n而 0..3 正是 MAGIC 区。于是：MAGIC 被覆盖、参数头错位，函数返回 0（成功）。下次上电读参数，MAGIC 不对 → 走“空片”分支 → 重灌默认值 → 用户存好的 PID 参数被冲掉。整条链上没有任何一个环节报错，这就是它“贵”的原因。\n\n正确做法：按 8 字节边界拆成多次写。 本项目 at24c02.c 的 `AT24C02_WriteBytes` 已经替做了：循环里算出本页还能写多少 `in_page = 8 - ((addr + done) & 7)`，取 `n = min(剩余长度, in_page)` 写一片，每片写完等一次写周期，直到写完。所以可以放心整段写，这是头文件里明确承诺的“已自动分页”。\n\n但驱动还替挡了另一件事，而且更值得学。 光分页还不够：如果起始地址加长度超过了 256（比如 `addr = 250`、`len = 10`），分页只是把越界部分继续往后写，最终仍然会绕回 0..3。所以 at24c02.c 在函数开头加了一道硬拦截：\n```c\nif ((uint16_t)addr + len > (uint16_t)AT24C02_TOTAL_SIZE) return 1U;\n```\n源码注释把理由写得很清楚：“函数自己写了‘越界会绕回’却不拦，等于把‘数据被悄悄改掉’当成正常路径”。这是一条很值得学的工程原则：器件会静默做错事，驱动必须把它变成显式的失败。 读函数 `AT24C02_ReadBytes` 也加了同样的拦截。\n\n给纪律： ① 参数区规划好，别让任何一笔写的末尾越过 256；② 自己写裸 EEPROM 驱动时，分页和越界检查都要自己补；③ 心里那个边界公式 `可写长度 = 8 - (addr & 7)`，且必须与起始地址同页。",
   "① 在纸（或 Excel）上把参数区画成 32 行 × 8 列的格子，标出 MAGIC 区、参数头、参数体、校准区各占哪几格；② 写一段实验代码：`AT24C02_WriteBytes(0) 先写一份正常参数`，然后故意调 `AT24C02_WriteBytes(250, buf, 10)`，看它返回什么（本项目返回 1 = 被拦住了）；③ 把这道越界拦截临时注释掉再跑一次（只在实验代码里改，不要改 FWLIB 源码），观察 0x00~0x03 确实被改写、CRC 立刻不过、下次上电重灌默认值，把这个现场亲眼看过一次，就再也不会忘；④ 最后把实验代码删掉，恢复调用驱动。",
   "/* 页写边界的账，以及驱动替挡下的两件事 */\n\n/* ① 边界公式：本次最多能写多少字节 */\n#define PAGE_LEFT(addr)  (8U - ((addr) & 0x07U))\n\n/*   addr = 0x10 → 0x10 & 7 = 0 → 可写 8\n *   addr = 0x15 → 0x15 & 7 = 5 → 可写 3（0x15,0x16,0x17）\n *   addr = 0xFA → 0xFA & 7 = 2 → 可写 6（0xFA..0xFF）\n *   再往后就回卷到 0x00，这正是要拦住的越界\n */\n\n/* ② 驱动内部的分片逻辑（at24c02.c 的实际做法，读它、信它） */\nuint8_t AT24C02_WriteBytes(uint8_t addr, const uint8_t *buf, uint16_t len)\n{\n    uint16_t done = 0;\n\n    if (buf == 0 || len == 0U) return 1U;\n\n    /* 越界硬拦截：不依赖“芯片会绕回”，而是显式失败 */\n    if ((uint16_t)addr + len > (uint16_t)AT24C02_TOTAL_SIZE) return 1U;\n\n    while (done < len) {\n        /* 本次能写多少：不能跨页（页内地址低 3 位必须同页） */\n        uint8_t  in_page = (uint8_t)(AT24C02_PAGE_SIZE -\n                                     ((addr + done) & (AT24C02_PAGE_SIZE - 1U)));\n        uint16_t n       = (uint16_t)(len - done);\n\n        if (n > (uint16_t)in_page) n = (uint16_t)in_page;\n\n        if (SYS_I2C_WriteBytes(AT24C02_I2C_ID, AT24C02_ADDR,\n                               (uint8_t)(addr + done), &buf[done], n) != SYS_I2C_OK) {\n            return 1U;\n        }\n        at24c02_wait_ready();       /* 每片写完都要等一个写周期 */\n        done = (uint16_t)(done + n);\n    }\n    return 0U;\n}\n\n/* ③ 参数区按页对齐存放，连“拆”都不需要发生，逻辑最干净：\n *   0x10  头 8 字节  → 正好一页\n *   0x18  体 12 字节 → 0x18 起 8 字节一页 + 0x20 起 4 字节，两页\n *   0x30  第二份头、0x38 第二份体（A/B 轮换用）\n */",
   "拿一份已知内容填满 0x00~0xFF（比如 buf[i] = i），然后调用 AT24C02_WriteBytes(0x1C, buf, 12)（0x1C 起 12 字节会跨页），最后把 0x18~0x2F 全部读回来比对逐字节等于写入内容，如果驱动没分页，会看到 0x1C..0x1F 写对、0x20..0x23 却跑回了 0x18..0x1B。\n再验证越界拦截：AT24C02_WriteBytes(250, buf, 10) 必须返回 1（拦住），而不是返回 0 却把 0x00~0x03 改掉。",
   "以为“I2C 会自己处理跨页”：回卷是芯片硬件行为，它老老实实按指令做，只是结果不是会误认为的那样。\n只看写函数返回值：回卷时它返回成功，返回值完全不能告诉数据错位了。\n参数区不规划、到处乱写地址：今天 0x10 明天 0x0E，早晚撞上页边界和越界，而且是几个月后才爆发。\n以为“读”也会回卷：读是顺序递增的，没有页的概念，`AT24C02_ReadBytes(0xF0, buf, 32)` 会一直读到 0x10F 而不回卷（本项目读函数用越界检查挡住它，所以超过 256 的读会返回错）。\n自己写裸驱动只做了分页、没做越界检查：分页只解决“跨页”，不解决“越过芯片末尾”，后者更要命（直接覆盖头部）。\n更隐蔽的一种：先把 MAGIC 写进去、再写参数体，结果参数体越界绕回把 MAGIC 抹了，顺序再对也没用，根子在地址规划。",
   "AT24C02_WriteBytes AT24C02_ReadBytes AT24C02_TOTAL_SIZE AT24C02_PAGE_SIZE AT24C02_ADDR_MAGIC AT24C02_ADDR_PARAM AT24C02_ADDR_CALIB AT24C02_MAGIC_VALUE SYS_I2C_WriteBytes SYS_I2C_ReadBytes 页写 跨页 回卷 绕回 静默 越界 地址规划 PAGE_LEFT"
  ],
  [
   "参数保存：MAGIC + 版本 + 长度 + CRC16，然后 A/B 双份轮换",
   "EEPROM 里读出来的东西永远不能当成可信数据，这不是谨慎，是必须：空片是全 0xFF、写到一半掉电是半截数据、页写回卷是错位数据、干扰是翻转位。所以一份参数需要自己的“信封”，这就是本步的内容，分两层。\n\n第一层：单项参数的“信封”。 固定长度的头 + 变长的体：\n```\n[0..3]  MAGIC    4 字节常量（本项目用 0xA5 系列；驱动头里给了 AT24C02_MAGIC_VALUE = 0xA5U）\n[4]     版本     改字段就改它，防止新老固件互相误读\n[5]     长度     = sizeof(Param_t)，结构体变了就拒收\n[6..7]  CRC16    覆盖 MAGIC+版本+长度，低字节在前\n[8..]   参数体\n```\n为什么要“长度”这一项？ 因为结构体会变。今天 Param_t 是 12 字节，明天加一个字段变 16 字节。如果只校验 CRC，改了结构体、CRC 也算得过去，读出来的却是按新布局解释的旧数据，字段整体错位，数值荒谬但不报错。长度字段让这种情况变成“直接拒收、回落默认值”。\n\n为什么要 CRC16 而不是简单累加和？ 累加和检测不出“两个字节同时变化且和不变”这类错误；CRC 对位移、突发错误都有更好的检测能力，而且本项目已经有现成的 `MODBUS_CRC16(buf, len)`（多项式 0xA001 = 0x8005 反射，初值 0xFFFF，低字节在前）。\n\n判“存过没有”用 `AT24C02_IsMagicSet(addr, magic)`。 这里有个必须知道的历史：这个函数以前叫 `AT24C02_IsBlank`，返回 `(v == magic) ? 0 : 1`，名字问“是不是空的”，参数却叫 magic，返回 1 表示“空”。而 W25QXX_IsBlank 的 1 也是“空”，但两边要靠脑子翻译一层。真用起来就是这样：`if (AT24C02_IsBlank(A, M)) { 写默认参数; }`，写的人很容易写成 `if (!AT24C02_IsBlank(...))`，于是每次上电都重灌默认参数、把用户设置冲掉，还不报错。现在改成正向问法：1 = 魔数在 = 参数存过，直接用；0 = 不在或读失败。本卡一律用新名字新语义。\n\n第二层：A/B 双份轮换抗掉电。 CRC 能告诉“这份坏了”，但如果只有一份，坏了就只剩默认值。所以开两块（A 和 B，各占一页以上），每份都带自己的 MAGIC + 版本 + 长度 + CRC，再另放一个“当前有效份”标志。\n保存顺序是关键：先写“非当前”的那一份并校验，再更新标志指向它。 掉电分析：\n· 在新份写到一半时掉电 → 标志还指老份，老份完整 → 正常启动，只丢最后一次改动；\n· 在新份写完之后、改标志之前掉电 → 标志仍指老份（老份也完整），新份虽然完整但暂时不用；\n· 标志改完之后掉电 → 标志指新份，新份完整 → 正常。\n任何时刻都至少有一份是完整的，这就是它比单份强的全部原因。若先改标志再写数据，掉电会得到“标志指向一份未写完的数据”，比单份更糟。\n\n加载时不要盲信标志。 标志本身也可能坏（空片 0xFF、写一半）。正确做法是：标志只是优先提示，真正的判据始终是那一份自身的 CRC；标志指向的那份 CRC 不过，就两份都试一遍，谁过用谁。\n\n这个思路和 ⑱ SPI Flash 断网缓存日志那张卡是同一个哲学，“先写数据、确认落盘，再用一次原子写更新状态标志”，可恢复写入的通用套路，跟介质是 EEPROM 还是 NOR Flash 无关，两张卡互相引用着看。",
   "① 定义参数结构体 Param_t（本项目是 5 个字段 + 3 字节补齐 = 12 字节）；② 规划地址：0x00~0x03 驱动魔数、0x10 头 A、0x18 体 A、0x30 头 B、0x38 体 B、0x40 有效份标志；③ 写 param_save：组头 → 算 CRC（低字节在前）→ 写非当前份 → 都成功后写标志；④ 写 param_load：读标志 → 试标志指的那份（MAGIC + 版本 + 长度 + CRC 四关）→ 不过就两份都试 → 都不过返回失败；⑤ 开机链路：AT24C02_Init 失败说明器件不在，直接用默认值继续跑；读不成功就写默认值并回写一次。",
   "/* 参数结构体与参数保存的完整链路（节选，详见 e 字段成品代码） */\ntypedef struct {\n    uint16_t kp_x100;      /* PID Kp ×100：1.25 → 125 */\n    uint16_t ki_x100;\n    uint16_t kd_x100;\n    uint16_t temp_alarm;   /* 报警阈值 ×10 摄氏度 */\n    uint8_t  report_s;     /* 上报周期（秒） */\n    uint8_t  reserved[3];  /* 补齐到 12 字节 */\n} Param_t;\n\n#define P25_HDR_A    0x10U\n#define P25_BODY_A   0x18U\n#define P25_HDR_B    0x30U\n#define P25_BODY_B   0x38U\n#define P25_AB_FLAG  0x40U\n#define P25_FLAG_A   0xA0U\n#define P25_FLAG_B   0xB0U\n\n/* 保存：写非当前份 → 成功后再改标志（顺序不能换） */\nuint8_t param_save(const Param_t *p)\n{\n    uint8_t next = (uint8_t)(s_slot ^ 1U);\n    uint8_t flag = (next == 0U) ? P25_FLAG_A : P25_FLAG_B;\n\n    SYS_I2C_Lock(SYS_I2C_1);        /* 多笔连续操作，整体持锁 */\n\n    if (next == 0U) {\n        if (param_write_slot(P25_HDR_A, P25_BODY_A, p) != 0U) {\n            SYS_I2C_Unlock(SYS_I2C_1);\n            return 1U;\n        }\n    } else {\n        if (param_write_slot(P25_HDR_B, P25_BODY_B, p) != 0U) {\n            SYS_I2C_Unlock(SYS_I2C_1);\n            return 1U;\n        }\n    }\n\n    /* 关键时刻：先确认数据写完，再用【一次原子写】更新标志 */\n    if (AT24C02_WriteByte(P25_AB_FLAG, flag) != 0U) {\n        SYS_I2C_Unlock(SYS_I2C_1);\n        return 2U;\n    }\n\n    SYS_I2C_Unlock(SYS_I2C_1);\n    s_slot = next;\n    return 0U;\n}\n\n/* 加载：标志只是提示，真正的判据是那一份自己的 CRC */\nuint8_t param_load(void)\n{\n    uint8_t flag = 0U;\n\n    if (AT24C02_ReadByte(P25_AB_FLAG, &flag) == 0U) {\n        if (flag == P25_FLAG_A) {\n            if (param_read_slot(P25_HDR_A, P25_BODY_A, &s_param) != 0U) {\n                s_slot = 0U; return 0U;\n            }\n        } else if (flag == P25_FLAG_B) {\n            if (param_read_slot(P25_HDR_B, P25_BODY_B, &s_param) != 0U) {\n                s_slot = 1U; return 0U;\n            }\n        }\n    }\n    /* 标志无效或那份 CRC 不过：两份都试，谁过用谁 */\n    if (param_read_slot(P25_HDR_A, P25_BODY_A, &s_param) != 0U) { s_slot = 0U; return 0U; }\n    if (param_read_slot(P25_HDR_B, P25_BODY_B, &s_param) != 0U) { s_slot = 1U; return 0U; }\n    return 1U;      /* 两份都不可信 */\n}",
   "在参数体里改一个字节（调试器直接写内存或故意写坏），下次上电应走“回落默认值并重写”分支，这是 CRC 在起作用。\n把 P25_FLAG_A 的值改成 0x00（模拟标志损坏），重新上电应能通过“两份都试一遍”把完整的那份读出来，参数不丢，这是 A/B 轮换在起作用。\n反向验证顺序的重要性：把 param_save 里的“先写数据再写标志”改成“先写标志再写数据”，在写数据阶段掉电（可以写死一个不会返回的错误来模拟），下次启动就会读到一份标志指向但内容不完整的数据，CRC 会拦住它，但已经失去了最后一次改动的和上一份数据的保护，只剩一份可用了。",
   "盲目相信 EEPROM 内容：不做校验直接把结构体 memcpy 到全局变量，坏数据会一路传到控制逻辑里，还可能让误判成算法 bug。\n只做 MAGIC 不做 CRC：MAGIC 只能回答“存过没有”，回答不了“这份内容对不对”。\n忘了“长度”字段：结构体一变，老数据被按新布局解释，字段整体错位，数值荒谬却一切“正常”。\nCRC 字节序写反：低字节在前。写反了两端都是同一个算法反而自洽，等换了第三方工具才发现不对，这类“自洽的错”最难查。\n保存时先改标志再写数据：掉电后标志指向半截数据，比只有一份还危险。\n加载时盲信标志：标志自己也会坏，真正的判据永远是那份数据自己的 CRC。\n用旧名 AT24C02_IsBlank 并且写反了取反：每次上电重灌默认参数，把用户设置冲掉还不报错，这是这个函数改名的全部理由。\n忘了“读不出来就当没存过”：AT24C02_IsMagicSet 在读失败时返回 0（当没存过），这是安全侧的选择，宁可重灌默认值，也不要拿一份来路不明的数据去跑业务。",
   "AT24C02_IsMagicSet AT24C02_MAGIC_VALUE AT24C02_ADDR_MAGIC AT24C02_ReadByte AT24C02_WriteByte AT24C02_WriteBytes AT24C02_ReadBytes MODBUS_CRC16 CRC16 0xA001 0xFFFF 低字节在前 MAGIC 版本 长度 校验 默认参数 回落 A/B 双份 轮换 掉电 原子 标志 param_save param_load Param_t"
  ],
  [
   "多任务下的锁、中断禁入，以及一份排错清单",
   "最后一步是“让它稳定地跑在真实系统里”。板2 是 FreeRTOS 多任务环境，I2C1 上有 24C02、MPU6050、（外接）OLED，如果不保护，随时会出“偶发乱码 / 数值离谱 / 写不进去”这类最难查的问题。\n\n为什么必须锁： I2C 事务是 `START → 地址 → 数据 → STOP` 的连续时序。两个任务各自的事务一旦交错，比如任务 A 发完从机地址、任务 B 插进来发了一个 START，从机的状态机就乱了，它可能把 B 的地址当成 A 的数据收下。所以锁的粒度是“一次完整事务”，不是单字节、也不是单个寄存器。\n\n谁在锁： sys_i2c.c 的 11 个公共入口，Init / IsDeviceReady / WriteByte / ReadByte / WriteBytes / ReadBytes / ReadRaw / WriteCmd / BusReset / Scan / WriteReg16 / ReadReg16，每一个都采用“先 SYS_I2C_Lock(id) → 调内部 _locked 实现 → SYS_I2C_Unlock(id)”的结构。所以单笔调用完全不用管锁。\n\n什么时候要自己加锁： 需要“连续多次事务中间不被打断”时。最典型的就是写一份参数 = 擦/写头 + 写体 + 改标志，这是一整段逻辑，中间被别的任务插进来读到“头已改、体没改”的半成品就坏了。做法是在外面再包一层：\n```\nSYS_I2C_Lock(SYS_I2C_1);\n... 多笔 SYS_I2C_xxx / 驱动调用 ...\nSYS_I2C_Unlock(SYS_I2C_1);\n```\n本项目用的是递归互斥量（xSemaphoreCreateRecursiveMutex / xSemaphoreTakeRecursive / xSemaphoreGiveRecursive），同一任务重复 Lock 只是计数 +1，不会自锁死，所以“外层包一段 + 内层公共函数各自加锁”可以安全嵌套。锁是惰性创建的（第一次用到某条总线才建），不要求先 Init、也不要求调度器已启动；粒度是每条总线一把锁，I2C1/I2C2/I2C3 互不影响。\n\n调度器未运行时加锁是空操作（上电初始化阶段单线程，本来就没并发），所以裸机路径完全不受影响。\n\n中断上下文：加锁会被跳过。 SYS_I2C_Lock 第一句就是 `if (__get_IPSR() != 0U) return;`，`__get_IPSR()` 是 Cortex-M 读 IPSR 寄存器的标准做法，非 0 就表示当前在异常/中断处理中。FreeRTOS 的互斥量在 ISR 里阻塞是非法操作（还可能触发任务切换），所以库选择直接跳过加锁。这意味着：在中断里调 SYS_I2C_xxx 仍然“能跑”，但没有任何互斥保护，必须自己保证它不和任务里的事务并发，正确做法是把访问丢给任务（队列/信号量），而不是在 ISR 里硬做。\n另外要：加锁不关中断、也不形成长临界区。OLED 刷一屏要 20~25ms，如果为了“安全”用 __disable_irq 去保护，整个系统的实时性就直接毁了，这就是他们选互斥量而不是关中断的原因。\n\n排错清单（按这个顺序走，八成问题在前三步就定位了）：\n· 扫不到地址 → SYS_I2C_Scan 先看总线上有谁；再查上拉（-2 起始条件失败基本就是上拉/总线忙）、供电、地址脚（A0~A2 / SA0 / AD0）、共地；8 位地址有没有忘右移。\n· 读回全 0xFF → 空片（从未写过）或写周期未结束（写命令已发出但芯片仍在忙）。检查写函数返回值、地址规划有没有越界被拦、是不是写到别处去了。\n· 偶发 NACK（-3） → 第一嫌疑是“写周期内接着发起新事务”（EEPROM 特有）；第二是上拉太弱/线太长导致上升沿不够快；第三是别的任务/中断在并发访问同一条总线（没加锁）。\n· 总线被拉死（-5 超时） → 某个从机被干扰后停在“以为还在收字节”的状态，把 SDA 一直拉低 → 调 SYS_I2C_BusReset(bus)，它发 9 个时钟 + STOP 把从机踢回空闲，再重新初始化本机 I2C。\n· 数据偶发错乱、偶尔 CRC 不过 → 十有八九是并发没保护，或线太长/没屏蔽。加锁 + 降速到 100kHz + 缩短走线，三招下去基本就干净了。\n\n一个总原则： 出问题先看错误码（SYS_I2C_ErrStr 会给中文提示，-2/-3/-4/-5 分别指向起始条件/地址/数据/超时），再用扫描看总线上有谁，最后才怀疑代码逻辑。I2C 的绝大部分故障都在物理层和并发上，不在算法里。",
   "① 把 param_save 用 SYS_I2C_Lock/Unlock 整体包起来（成品代码里已经这么做）；② 检查 ISR 里有没有直接调 SYS_I2C_xxx，有的话改成向队列投递、由任务执行；③ 打印出每次 I2C 失败的错误码和 SYS_I2C_ErrStr，让日志自己能说话；④ 把“扫描 + 点名”放进开机自检，让每次上电都能看到总线上的实际情况；⑤ 遇到 -5 超时，先 BusReset 再重试一次（成品代码的 bus_read_with_recovery 就是这个模式）。",
   "/* 多任务安全的写参数：整体持锁 + 出错用 BusReset 自救 */\nuint8_t param_commit_safe(const Param_t *p)\n{\n    uint8_t r;\n\n    /* 整段“多笔连续事务”必须在同一把锁里完成。\n     *   sys_i2c 的每个公共入口内部也会加锁，本项目是递归锁，\n     *   同任务重复 Lock 只是计数 +1，不会自锁死。 */\n    SYS_I2C_Lock(SYS_I2C_1);\n    r = param_save(p);\n    SYS_I2C_Unlock(SYS_I2C_1);\n\n    if (r == 0U) return 0U;\n\n    /* 失败了一次：救总线，再整体重试一次 */\n    SYS_I2C_BusReset(SYS_I2C_1);        /* 9 个时钟 + STOP + 重新初始化 */\n\n    SYS_I2C_Lock(SYS_I2C_1);\n    r = param_save(p);\n    SYS_I2C_Unlock(SYS_I2C_1);\n    return r;\n}\n\n/* 中断里绝对不要这么写：\n *   void EXTI0_IRQHandler(void)\n *   {\n *       AT24C02_WriteByte(0x10, 1U);   // 错。SYS_I2C_Lock 在 ISR 里\n *                                       // 被 __get_IPS R() 判断后直接跳过，\n *                                       // 这一次写没有任何互斥保护\n *   }\n *   同时它还要等 5ms 写周期，把中断拖成几十毫秒。\n *\n *   正确做法：中断里只投递消息，由任务去写：\n *   void EXTI0_IRQHandler(void)\n *   {\n *       BaseType_t woken = pdFALSE;\n *       xQueueSendFromISR(g_i2c_q, &msg, &woken);\n *       portYIELD_FROM_ISR(woken);\n *   }\n */\n\n/* 出错自查表（打印出来贴在工位上）：\n *   -2 ERR_START   起始条件失败  → 上拉缺失 / 总线忙 / 引脚配置错\n *   -3 ERR_ADDR    器件无应答    → 地址错(7位/8位) / 没供电 / 写周期内重发\n *   -4 ERR_DATA    数据阶段 NACK → 寄存器号不对 / 器件类型不匹配\n *   -5 ERR_TIMEOUT 等标志超时    → 总线被从机拉死 → BusReset 后重试\n *   -6 ERR_BUS     总线错误      → 时序被干扰 → 降速 / 缩短走线\n *   -1 ERR_PARAM   参数非法      → 指针为空 / len 为 0 / id 越界\n */",
   "所有任务对同一条总线的访问都不再出现“偶发乱码”：把 OLED 刷屏任务（连续几十次事务）和参数保存任务同时跑起来，反复触发，数据依然正确，说明锁的粒度选对了。\n反向验证：把 param_save 外面的 Lock/Unlock 去掉，同时高频跑 OLED 刷屏，会看到写参数偶发失败或 CRC 不过，这就是并发不加锁的现场（因为复现概率低，需要多跑一会儿）。\n再验证 BusReset：人为把 SDA 短接到 GND 制造“总线被拉死”，所有访问都会返回 -5；松开后调用 SYS_I2C_BusReset，总线立刻恢复。",
   "用 __disable_irq 保护 I2C 事务：刷一屏 20~25ms 的临界区会毁掉整个系统的实时性，这不是“更安全”，是更糟。\n在 ISR 里调 SYS_I2C_xxx 还以为是受保护的：加锁被跳过，等于没有互斥。\n以为锁是“按寄存器”或“按字节”：粒度是一次完整事务，粗了才有意义。\n持着外层锁去调 SYS_I2C_Scan 或刷一整屏：递归锁同任务不会死锁，但别的任务会一直等到整段结束，实时性照样崩。\n多笔操作不在外层加锁：单笔调用各自加锁不代表“两笔之间没人插进来”，写参数最典型。\n调度器没启动时以为锁能防住什么：那时是单线程，本来就没有并发。\n遇到 -5 只重试不救总线：从机还钉在 SDA 上，重试一万次也一样，必须先 BusReset。\n把错误码丢掉只看“成功/失败”：-2/-3/-4/-5 已经把故障分层，丢掉它等于把排查线索扔掉。",
   "SYS_I2C_Lock SYS_I2C_Unlock SYS_I2C_BusReset SYS_I2C_ErrStr SYS_I2C_ERR_START SYS_I2C_ERR_ADDR SYS_I2C_ERR_DATA SYS_I2C_ERR_TIMEOUT SYS_I2C_ERR_BUS SYS_I2C_ERR_PARAM SYS_I2C_COUNT __get_IPS R xSemaphoreCreateRecursiveMutex xSemaphoreTakeRecursive xSemaphoreGiveRecursive portMAX_DELAY 递归互斥量 xTaskGetSchedulerState taskSCHEDULER_RUNNING 中断 ISR 队列 xQueueSendFromISR portYIELD_FROM_ISR 临界区 实时性"
  ]
 ]
}
"""
